window.TADABBUR_TUR = {"_meta":{"description":"تدبّر سورة الطور (٥٢)، وسورةٌ مكّيّةٌ. محورُها تقريرُ وقوعِ عذابِ الله وأهوالِ يومِ القيامة، ومقابلةُ عذابِ المكذّبين بنعيمِ المتّقين وإلحاقِ ذرّيّتهم بهم، وإقامةُ الحجّةِ على المشركين بسلسلةِ أسئلةٍ تعجيزية (أم...)، والأمرُ بالتذكيرِ والصبرِ والتسبيح. فيها «إن عذاب ربك لواقع»، و«والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم»، و«أم خلقوا من غير شيء أم هم الخالقون»، و«واصبر لحكم ربك فإنك بأعيننا».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":52,"name":"الطور","total_ayahs":49,"audio":[1,7,17,21,26,29,35,43,48,49],"passages":[{"title":"القسمُ بالآياتِ على وقوعِ العذاب وأهوالِ القيامة","range":[1,11],"theme":"القسمُ بالطورِ والكتابِ المسطورِ والبيتِ المعمورِ والسقفِ المرفوعِ والبحرِ المسجورِ على أنّ عذابَ الله واقعٌ لا دافعَ له، يومَ تمور السماءُ وتسير الجبال، فويلٌ يومئذٍ للمكذّبين","verses":[{"n":1,"reflection":{"text":"«والطور»: أقسم الله بالطورِ (الجبلِ الذي كلّم الله عليه موسى)؛ ففي هذا قسمٌ بآيةٍ من آياتِ الله؛ فعظّم آياتِ الله التي أقسم بها، فالطورُ مكانٌ عظّمه الله بتكليمِ موسى، فاعتبر بآياتِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله التي أقسم بها، والاعتبارُ بها."},"action":{"text":"تأمّل قسمَ الله بالطور: أقسم الله بالطور، وهو الجبلُ الذي كلّم الله عليه موسى عليه السلام بطورِ سيناء «والطور»؛ ففي هذا قسمٌ من الله بالطورِ لعظمته وشرفه، لكونه موضعَ تكليمِ موسى؛ فعظّم أنت آياتِ الله وأماكنَ فضله التي أقسم بها؛ فالطورُ عظّمه الله بتكليمِ موسى عليه؛ وناديناه من جانبِ الطورِ الأيمن؛ وطورِ سينين؛ فأقسم الله به لشرفه ومنزلته؛ فاعتبر بآياتِ الله وعظّمها؛ فمن عظّم آياتِ الله اهتدى وانتفع؛ فاجعل تعظيمَ آياتِ الله والاعتبارَ بها دأبك."}},{"n":2,"reflection":{"text":"«وكتاب مسطور»، وأقسم بكتابٍ مكتوبٍ مسطور (اللوحِ المحفوظِ أو القرآنِ أو الكتب)؛ ففي هذا قسمٌ بالكتابِ المكتوب؛ فعظّم كتابَ الله المكتوب، فالله أقسم به لشرفه، فاعتنِ بالقرآنِ وكتبِ الوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ كتابِ الله والاعتناءُ به."},"action":{"text":"تأمّل القسمَ بالكتاب: وأقسم الله بكتابٍ مسطورٍ، أي مكتوبٍ مصفوفِ السطور؛ وهو اللوحُ المحفوظ، أو القرآن، أو الكتبُ المنزَّلة، أو ما تكتبه الملائكة «وكتاب مسطور»؛ ففي هذا قسمٌ بالكتابِ المسطورِ المكتوبِ لشرفه وعظمته؛ فأقسم الله به لعظمِ شأنه؛ فعظّم أنت كتابَ الله المكتوبَ المنزَّل؛ فالقرآنُ كلامُ الله المكتوبُ المحفوظ؛ إنه لقرآنٌ كريم، في كتابٍ مكنون؛ في صحفٍ مكرّمةٍ مرفوعةٍ مطهّرة؛ فاعتنِ بالقرآنِ وكتبِ الوحي تلاوةً وتدبّرًا وعملًا؛ فمن عظّم كتابَ الله وأقبل عليه اهتدى؛ فاجعل تعظيمَ كتابِ الله والاعتناءَ به دأبك."}},{"n":3,"reflection":{"text":"«في رق منشور»: في رقٍّ (صحيفةٍ رقيقة) منشورٍ مبسوط؛ ففي هذا تتمّةُ وصفِ الكتاب؛ فتأمّل عنايةَ الله بحفظِ الوحيِ وكتابته، فالوحيُ محفوظٌ مكتوبٌ منشور، فاعتنِ بالوحيِ المحفوظ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتناءُ بالوحيِ المحفوظ، وإدراكُ عنايةِ الله بحفظه."},"action":{"text":"تأمّل وصفَ الكتاب: ذلك الكتابُ المسطورُ في رقٍّ، وهو الصحيفةُ الرقيقةُ التي يُكتَب فيها، منشورٍ مبسوطٍ ظاهرٍ يُقرَأ «في رق منشور»؛ ففي هذا تتمّةُ وصفِ الكتابِ المقسَمِ به، بأنه مكتوبٌ في رقٍّ منشورٍ مبسوط؛ فوصفه بالكتابةِ والنشرِ لظهوره ووضوحه؛ فتأمّل أنت عنايةَ الله بحفظِ الوحيِ وكتابته ونشره؛ فالوحيُ محفوظٌ مكتوبٌ منشورٌ ظاهر؛ بل هو قرآنٌ مجيد، في لوحٍ محفوظ؛ إنا نحن نزّلنا الذكرَ وإنا له لحافظون؛ فعنايةُ الله بحفظِ كتابه وكتابته دليلُ عظمته؛ فاعتنِ أنت بالوحيِ المحفوظ، واقرأه وتدبّره واعمل به؛ فمن اعتنى بالوحيِ المحفوظِ اهتدى؛ فاجعل الاعتناءَ بالوحيِ المحفوظِ وإدراكَ عنايةِ الله بحفظه دأبك."}},{"n":4,"reflection":{"text":"«والبيت المعمور»، وأقسم بالبيتِ المعمورِ في السماءِ الذي تعمره الملائكةُ بالعبادة؛ ففي هذا قسمٌ بموضعِ عبادةِ الملائكة؛ فتأمّل عبادةَ الملائكةِ الدائمةَ في البيتِ المعمور، واقتدِ بهم في عمارةِ بيوتِ الله بالعبادة، فعمارةُ المساجدِ بالطاعةِ من شأنِ العابدين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عمارةُ بيوتِ الله بالعبادة، والاقتداءُ بالملائكة."},"action":{"text":"تأمّل القسمَ بالبيتِ المعمور: وأقسم الله بالبيتِ المعمورِ، وهو بيتٌ في السماءِ السابعةِ حِيالَ الكعبة، يدخله كلَّ يومٍ سبعون ألفَ مَلَكٍ يعبدون الله فيه ثم لا يعودون إليه، تعمره الملائكةُ بالعبادةِ والطواف «والبيت المعمور»؛ ففي هذا قسمٌ بالبيتِ المعمورِ الذي تعمره الملائكةُ بالعبادة، لعظمته وشرفه؛ فهو موضعُ عبادةِ الملائكةِ الدائمة؛ فتأمّل أنت عبادةَ الملائكةِ الدائمةَ في البيتِ المعمور؛ يسبّحون الليلَ والنهارَ لا يفترون؛ فاقتدِ بهم في عمارةِ بيوتِ الله (المساجد) بالعبادةِ والصلاةِ والذكر؛ إنما يعمر مساجدَ الله من آمن بالله واليومِ الآخر؛ في بيوتٍ أذن الله أن تُرفَع ويُذكَر فيها اسمه، يسبّح له فيها بالغدوِّ والآصال؛ فعمارةُ المساجدِ بالطاعةِ والعبادةِ من شأنِ العابدين المقتدين بالملائكة؛ فمن عمر بيوتَ الله بالعبادةِ نال الأجرَ والقرب؛ فاجعل عمارةَ بيوتِ الله بالعبادةِ اقتداءً بالملائكةِ دأبك."}},{"n":5,"reflection":{"text":"«والسقف المرفوع»، وأقسم بالسماءِ (السقفِ المرفوعِ فوق الأرض)؛ ففي هذا قسمٌ بالسماءِ المرفوعة؛ فتأمّل السماءَ سقفًا محفوظًا مرفوعًا بلا عمد، فمن رفعها قادرٌ على كلِّ شيء، فعظّم قدرةَ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ قدرةِ الله في رفعِ السماء، والتفكّرُ فيها."},"action":{"text":"تأمّل القسمَ بالسماء: وأقسم الله بالسقفِ المرفوع، وهي السماءُ التي رفعها الله فوق الأرضِ سقفًا محفوظًا بلا عمدٍ ترونها «والسقف المرفوع»؛ ففي هذا قسمٌ بالسماءِ المرفوعةِ سقفًا لعظمتها ودلالتها على قدرةِ الله؛ فرفعها بقدرته سقفًا محفوظًا؛ فتأمّل أنت السماءَ سقفًا مرفوعًا محفوظًا بلا عمدٍ تراها؛ وجعلنا السماءَ سقفًا محفوظًا وهم عن آياتها معرضون؛ الله الذي رفع السماواتِ بغيرِ عمدٍ ترونها؛ أفلم ينظروا إلى السماءِ فوقهم كيف بنيناها؛ فمن رفع السماءَ سقفًا محفوظًا قادرٌ على كلِّ شيء، وعلى البعثِ والعذاب؛ فعظّم أنت قدرةَ الله في رفعِ السماءِ وحفظها؛ فمن تفكّر في رفعِ السماءِ عظّم الخالقَ وأيقن بقدرته؛ فاجعل تعظيمَ قدرةِ الله والتفكّرَ في السماءِ المرفوعةِ دأبك."}},{"n":6,"reflection":{"text":"«والبحر المسجور»، وأقسم بالبحرِ المسجورِ (المملوءِ، أو الموقَدِ نارًا يومَ القيامة)؛ ففي هذا قسمٌ بالبحرِ آيةً من آياتِ الله؛ فتأمّل البحرَ آيةً من آياتِ الله ونعمةً، فمن سخّره قادرٌ على العذابِ الذي أقسم عليه، فاعتبر بآياتِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آيةِ البحر، والاستدلالُ بها على قدرةِ الله."},"action":{"text":"تأمّل القسمَ بالبحر: وأقسم الله بالبحرِ المسجور، أي المملوءِ الممتلئِ بالماء، أو الموقَدِ المُحمى نارًا يومَ القيامة، أو المحبوسِ الممنوعِ من إغراقِ الأرض «والبحر المسجور»؛ ففي هذا قسمٌ بالبحرِ لعظمته ودلالته على قدرةِ الله؛ فأقسم به آيةً من آياته ونعمةً من نعمه؛ فتأمّل أنت البحرَ العظيمَ الممتلئَ بالماء، آيةً من آياتِ الله ونعمةً من نعمه؛ وهو الذي سخّر البحرَ لتأكلوا منه لحمًا طريًّا؛ الله الذي سخّر لكم البحرَ لتجريَ الفلكُ فيه بأمره؛ وإذا البحارُ سُجِّرت؛ فمن سخّر البحرَ وملأه بالماءِ قادرٌ على العذابِ الذي أقسم عليه؛ فاعتبر بآياتِ الله في البحرِ على قدرته ووحدانيته؛ فمن تفكّر في آيةِ البحرِ أيقن بالخالق؛ فاجعل التفكّرَ في آيةِ البحرِ والاستدلالَ بها دأبك."}},{"n":7,"reflection":{"text":"«إن عذاب ربك لواقع»: إنّ عذابَ ربّك بالمكذّبين لواقعٌ لا محالة؛ ففي هذا جوابُ القسمِ بتقريرِ وقوعِ العذاب؛ فأيقن بوقوعِ عذابِ الله بالمكذّبين، فاحذره بالإيمانِ والعمل، فعذابُ الله واقعٌ حتمًا بمن استحقّه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوقوعِ عذابِ الله، والحذرُ منه بالإيمانِ والعمل."},"action":{"text":"تأمّل تقريرَ وقوعِ العذاب: هذا جوابُ القسم: إنّ عذابَ ربّك، أيها الرسولُ، بالمكذّبين والكافرين لواقعٌ كائنٌ لا محالة، حقٌّ لا شكَّ فيه «إن عذاب ربك لواقع»؛ ففي هذا جوابُ القسمِ العظيمِ بتقريرِ وقوعِ عذابِ الله بالمكذّبين؛ فأكّد وقوعَه بالقسمِ بالآياتِ العظيمة؛ فأيقن أنت بوقوعِ عذابِ الله بالمكذّبين والكافرين يقينًا جازمًا؛ فما وعد الله به من العذابِ واقعٌ حتمًا؛ ووقع القولُ عليهم بما ظلموا؛ إنّ عذابَ ربّهم غيرُ مأمون؛ فاحذر أنت العذابَ بالإيمانِ والعملِ الصالحِ والتقوى؛ فعذابُ الله واقعٌ حتمًا بمن استحقّه بكفره وظلمه؛ فمن أيقن بوقوعِ العذابِ وحذره بالعملِ نجا، ومن أنكره أو أمنه هلك؛ فاجعل اليقينَ بوقوعِ عذابِ الله والحذرَ منه بالإيمانِ والعملِ دأبك."}},{"n":8,"reflection":{"text":"«ما له من دافع»: ما لعذابِ الله من دافعٍ يدفعه أو مانعٍ يمنعه؛ ففي هذا بيانُ حتميّةِ العذابِ وأنه لا رادَّ له؛ فاعلم أنه لا يدفع عذابَ الله شيء، فلا تعتمد على شفيعٍ ولا ناصرٍ من دونه، فالنجاةُ في الإيمانِ والعملِ لا في غيرهما.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنه لا رادَّ لعذابِ الله، والنجاةُ بالإيمانِ والعمل."},"action":{"text":"تأمّل حتميّةَ العذاب: ما لعذابِ الله الواقعِ بالمكذّبين من دافعٍ يدفعه، ولا مانعٍ يمنعه، ولا رادٍّ يردّه؛ فهو نازلٌ بهم لا محالة «ما له من دافع»؛ ففي هذا بيانُ أنّ عذابَ الله لا يدفعه شيء، ولا يردّه أحد؛ فإذا وقع فلا مانعَ له؛ فاعلم أنت أنه لا يدفع عذابَ الله شيء، ولا ينفع من الله شفيعٌ ولا ناصرٌ ولا مالٌ ولا ولد؛ فلا مردَّ له من الله؛ ليس لها من دونِ الله كاشفة؛ يومَ لا تملك نفسٌ لنفسٍ شيئًا؛ فلا تعتمد على شفيعٍ ولا ناصرٍ من دونِ الله لدفعِ عذابه؛ فالنجاةُ من عذابِ الله في الإيمانِ والعملِ الصالحِ والتقوى، لا في غيرها؛ فمن آمن وعمل صالحًا نجا، ومن اعتمد على غيرِ الله خُذِل؛ فاجعل إدراكَ أنه لا رادَّ لعذابِ الله، والنجاةَ بالإيمانِ والعملِ، دأبك."}},{"n":9,"reflection":{"text":"«يوم تمور السماء مورا»: يومَ تضطرب السماءُ وتتحرّك اضطرابًا شديدًا؛ ففي هذا بيانُ أهوالِ يومِ القيامة؛ فاستعدّ ليومٍ تضطرب فيه السماء، فأهوالُ القيامةِ عظيمة، فاعمل لذلك اليومِ قبل مجيئه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ القيامة، والعملُ له قبل أهواله."},"action":{"text":"تأمّل أهوالَ القيامة: يقع العذابُ يومَ تمور السماءُ مورًا، أي تضطرب وتتحرّك وتدور اضطرابًا شديدًا، وتتموّج، اختلالًا لنظامها عند قيامِ الساعة «يوم تمور السماء مورا»؛ ففي هذا بيانُ بعضِ أهوالِ يومِ القيامة: اضطرابُ السماءِ وموْرها؛ فتضطرب السماءُ المحكمةُ وتتحرّك من هولِ ذلك اليوم؛ فاستعدّ أنت ليومٍ تضطرب فيه السماءُ وتمور؛ إذا السماءُ انشقّت؛ يومَ تكون السماءُ كالمهل؛ فُتِحت السماءُ فكانت أبوابًا؛ فأهوالُ القيامةِ عظيمةٌ تضطرب لها السماوات؛ فاعمل أنت لذلك اليومِ العظيمِ بالإيمانِ والعملِ الصالحِ قبل مجيئه؛ فمن استعدّ ليومِ القيامةِ بالعملِ نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ القيامةِ والعملَ له دأبك."}},{"n":10,"reflection":{"text":"«وتسير الجبال سيرا»، وتسير الجبالُ عن أماكنها سيرًا حتى تصير هباءً؛ ففي هذا تتمّةُ أهوالِ القيامة؛ فاستعدّ ليومٍ تسير فيه الجبالُ الراسيات، فإذا زالت الجبالُ الثوابتُ فما بالك بغيرها، فاعمل لذلك اليوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ زوالِ الجبال، والعملُ له."},"action":{"text":"تأمّل تتمّةَ الأهوال: وتسير الجبالُ الراسياتُ الثوابتُ عن أماكنها سيرًا، فتتحرّك وتزول وتتفتّت حتى تصير هباءً منبثًّا وكثيبًا مهيلًا «وتسير الجبال سيرا»؛ ففي هذا بيانُ هولٍ آخرَ من أهوالِ القيامة: سيرُ الجبالِ وزوالها؛ فالجبالُ الراسياتُ الثوابتُ تسير وتزول من هولِ ذلك اليوم؛ فاستعدّ أنت ليومٍ تسير فيه الجبالُ وتزول؛ وتسير الجبالُ سيرًا؛ وترى الجبالَ تحسبها جامدةً وهي تمرُّ مرَّ السحاب؛ وحُمِلت الأرضُ والجبالُ فدُكّتا دكّةً واحدة؛ ويومَ نسيّر الجبال؛ فإذا زالت الجبالُ الثوابتُ الراسياتُ فما بالك بغيرها من الأهوال؟ فاعمل أنت لذلك اليومِ العظيمِ قبل مجيئه؛ فمن استعدّ له بالعملِ نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ زوالِ الجبالِ والعملَ له دأبك."}},{"n":11,"reflection":{"text":"«فويل يومئذ للمكذبين»: فويلٌ وهلاكٌ يومئذٍ للمكذّبين بالحقِّ والبعث؛ ففي هذا بيانُ عاقبةِ المكذّبين؛ فاحذر التكذيبَ الذي يورث الويلَ يومَ القيامة، فصدّق بالحقِّ واعمل به، فالتكذيبُ سببُ الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بالحقِّ والعملُ به، والحذرُ من التكذيب."},"action":{"text":"تأمّل عاقبةَ المكذّبين: فويلٌ، أي هلاكٌ وعذابٌ شديد، أو وادٍ في جهنّم، يومئذٍ (يومَ القيامة) للمكذّبين بالله ورسوله واليومِ الآخرِ والحق «فويل يومئذ للمكذبين»؛ ففي هذا بيانُ أنّ للمكذّبين الويلَ والهلاكَ يومَ القيامة؛ فجزاءُ تكذيبهم الويلُ والعذاب؛ فاحذر أنت التكذيبَ بالحقِّ والبعثِ الذي يورث الويلَ يومَ القيامة؛ فصدّق بالحقِّ الذي جاء به الرسولُ واعمل به؛ ويلٌ يومئذٍ للمكذّبين؛ فويلٌ للذين كفروا من مشهدِ يومٍ عظيم؛ فالتكذيبُ بالحقِّ سببُ الهلاكِ والويل؛ فمن صدّق بالحقِّ وعمل به نجا، ومن كذّب به فله الويل؛ فاجعل التصديقَ بالحقِّ والعملَ به وتركَ التكذيبِ دأبك."}}]},{"title":"عذابُ المكذّبين ودعُّهم إلى النار","range":[12,16],"theme":"وصفُ المكذّبين بالخوضِ واللعب، ودعِّهم إلى نارِ جهنّمَ دعًّا وتوبيخِهم بأنها التي كانوا بها يكذّبون: أفسحرٌ هذا، اصلوها فاصبروا أو لا تصبروا سواءٌ عليكم إنما تُجزَون ما كنتم تعملون","verses":[{"n":12,"reflection":{"text":"«الذين هم في خوض يلعبون»: المكذّبون الذين هم في باطلٍ يخوضون فيه لاعبين لاهين؛ ففي هذا بيانُ حالِ المكذّبين في الخوضِ واللعب؛ فاحذر الخوضَ في الباطلِ واللعبَ واللهو، فاشتغل بالحقِّ والجدِّ في العمل، فالخوضُ في الباطلِ من صفاتِ الهالكين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجدُّ في الحقِّ والعمل، وتركُ الخوضِ في الباطلِ واللعب."},"action":{"text":"تأمّل حالَ المكذّبين: المكذّبون هم الذين في خوضٍ، أي في باطلٍ يخوضون فيه بالتكذيبِ والاستهزاءِ بآياتِ الله، يلعبون ويلهون، لا يجدّون في طلبِ الحقِّ ولا يعملون للآخرة «الذين هم في خوض يلعبون»؛ ففي هذا بيانُ حالِ المكذّبين: الخوضُ في الباطلِ واللعبُ واللهوُ والغفلةُ عن الحق؛ فشغلهم الخوضُ في الباطلِ عن الحق؛ فاحذر أنت الخوضَ في الباطلِ من التكذيبِ والاستهزاءِ بالدينِ والغيبةِ والكذب؛ واحذر اللعبَ واللهوَ والغفلةَ عن الحقِّ والعمل؛ وإذا رأيت الذين يخوضون في آياتنا فأعرض عنهم؛ وكنّا نخوض مع الخائضين ونكذّب بيومِ الدين؛ فاشتغل أنت بالحقِّ والجدِّ في العملِ للآخرة؛ فالخوضُ في الباطلِ واللعبُ من صفاتِ الهالكين المكذّبين؛ فمن جدَّ في الحقِّ والعملِ نجا، ومن خاض في الباطلِ ولعب هلك؛ فاجعل الجدَّ في الحقِّ وتركَ الخوضِ في الباطلِ دأبك."}},{"n":13,"reflection":{"text":"«يوم يدعون إلى نار جهنم دعا»: يومَ يُدفَعون إلى نارِ جهنّمَ دفعًا بعنفٍ وشدّة؛ ففي هذا بيانُ إهانةِ المكذّبين يومَ القيامة؛ فاحذر أن تُدَعَّ إلى النارِ بهذه الإهانة، فاعمل لتنجو منها، فإهانةُ المكذّبين جزاءُ تكذيبهم واستكبارهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنجاةِ من النار، والحذرُ من الإهانةِ فيها."},"action":{"text":"تأمّل إهانةَ المكذّبين: يقع العذابُ يومَ يُدَعّون، أي يُدفَعون ويُساقون بعنفٍ وشدّةٍ وإهانة، إلى نارِ جهنّمَ دعًّا، فيُدفَعون في أقفيتهم إليها «يوم يدعون إلى نار جهنم دعا»؛ ففي هذا بيانُ إهانةِ المكذّبين يومَ القيامة، بدفعهم إلى النارِ بعنفٍ وشدّة؛ فيُساقون إليها مهانين مدفوعين؛ فاحذر أنت أن تُدَعَّ وتُدفَع إلى النارِ بهذه الإهانةِ والغلظة؛ فاعمل عملًا صالحًا لتنجو منها؛ خذوه فاعتلوه إلى سواءِ الجحيم؛ يومَ يُسحَبون في النارِ على وجوههم؛ فإهانةُ المكذّبين وسوقُهم إلى النارِ بعنفٍ جزاءُ تكذيبهم واستكبارهم في الدنيا؛ فمن عمل للنجاةِ من النارِ نجا وأُكرِم، ومن كذّب أُهين ودُعَّ إليها؛ فاجعل العملَ للنجاةِ من النارِ دأبك."}},{"n":14,"reflection":{"text":"«هذه النار التي كنتم بها تكذبون»: يُقال لهم توبيخًا: هذه النارُ التي كنتم بها في الدنيا تكذّبون؛ ففي هذا تقريعُ المكذّبين بالنار؛ فاحذر التكذيبَ بالنارِ فإنها حقّ، فأيقن بها واعمل للنجاةِ منها، فالتكذيبُ بالنارِ لا يدفعها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالنارِ والعملُ للنجاةِ منها، وتركُ التكذيبِ بها."},"action":{"text":"تأمّل تقريعَ المكذّبين: يُقال للمكذّبين وهم يُدَعّون إلى النارِ توبيخًا وتقريعًا: هذه النارُ التي كنتم بها في الدنيا تكذّبون وتستهزئون؛ فذوقوها الآن «هذه النار التي كنتم بها تكذبون»؛ ففي هذا تقريعٌ للمكذّبين بالنارِ التي كذّبوا بها؛ فلمّا عاينوها قيل لهم هذه ما كنتم به تكذّبون؛ فاحذر أنت التكذيبَ بالنارِ والعذاب؛ فأيقن بالنارِ وعذابها واعمل للنجاةِ منها؛ هذه النارُ التي كنتم بها تكذّبون، أفسحرٌ هذا؛ يُدَعّون إلى نارِ جهنّم؛ فالتكذيبُ بالنارِ لا يدفعها ولا يمنعها؛ بل تقع بالمكذّبين لا محالة؛ فمن أيقن بالنارِ وعمل للنجاةِ منها نجا، ومن كذّب بها وقع فيها؛ فاجعل اليقينَ بالنارِ والعملَ للنجاةِ منها دأبك."}},{"n":15,"reflection":{"text":"«أفسحر هذا أم أنتم لا تبصرون»: يُقال لهم: أفسحرٌ هذا العذابُ الذي ترونه كما كنتم تقولون في القرآنِ سحر، أم أنتم لا تبصرون؟ ففي هذا توبيخهم بما كانوا يصفون به الحقّ؛ فاحذر وصفَ الحقِّ بالسحرِ أو العمى عنه، فأبصر الحقَّ واتّبعه، فوصفُ الحقِّ بالسحرِ من العناد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إبصارُ الحقِّ واتّباعُه، وتركُ وصفِه بالسحر."},"action":{"text":"تأمّل توبيخهم: يُقال للمكذّبين وهم في النارِ توبيخًا: أفسحرٌ هذا العذابُ الذي تعاينونه، كما كنتم تقولون في القرآنِ والوحيِ إنه سحر؟ أم أنتم لا تبصرون الحقَّ كما كنتم تدّعون أنكم لا تبصرون آياتِ الله؟ «أفسحر هذا أم أنتم لا تبصرون»؛ ففي هذا توبيخُ المكذّبين بما كانوا يصفون به الحقَّ في الدنيا من السحرِ والعمى؛ فبكّتهم بما كانوا يقولون؛ فلمّا كذّبوا الوحيَ بأنه سحر، قيل لهم أفسحرٌ هذا العذاب؟ فاحذر أنت وصفَ الحقِّ بالسحرِ أو الإعراضَ عنه كأنك لا تبصره؛ فأبصر الحقَّ واتّبعه ولا تصفه بالباطل؛ بل سحرتم أعينَنا بل نحن قومٌ مسحورون؛ هذا سحرٌ مبين؛ فوصفُ الحقِّ بالسحرِ والعمى عنه من العنادِ والمكابرة؛ فمن أبصر الحقَّ واتّبعه نجا، ومن وصفه بالسحرِ وأعرض عنه هلك؛ فاجعل إبصارَ الحقِّ واتّباعَه دأبك."}},{"n":16,"reflection":{"text":"«اصلوها فاصبروا أو لا تصبروا سواء عليكم إنما تجزون ما كنتم تعملون»: يُقال لهم: ادخلوها فذوقوا حرّها، اصبروا أو لا تصبروا سواءٌ عليكم، إنما تُجزَون بأعمالكم؛ ففي هذا بيانُ أنّ الجزاءَ بالعمل؛ فاعلم أنّ ما تُجزى به هو عملك، فاعمل صالحًا لتُجزى خيرًا، فالجزاءُ بقدرِ العمل، والصبرُ عند العذابِ لا ينفع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ للجزاءِ الحسن، وإدراكُ أنّ الجزاءَ بالعمل."},"action":{"text":"تأمّل أنّ الجزاءَ بالعمل: يُقال للمكذّبين: اصلوها وادخلوها وذوقوا حرّها؛ فاصبروا على عذابها أو لا تصبروا، سواءٌ عليكم في الحالين، فلن يُخفَّف عنكم ولن تخرجوا منها؛ إنما تُجزَون جزاءَ ما كنتم تعملون في الدنيا من الكفرِ والمعاصي «اصلوها فاصبروا أو لا تصبروا سواء عليكم إنما تجزون ما كنتم تعملون»؛ ففي هذا بيانُ أنّ جزاءَ المكذّبين النارُ، وأنّ صبرهم وجزعهم سواء، وأنّ الجزاءَ بالعمل؛ فما جُوزوا إلا بأعمالهم؛ فاعلم أنت أنّ ما تُجزى به يومَ القيامةِ هو عملك في الدنيا؛ فاعمل عملًا صالحًا لتُجزى به خيرًا؛ فمن يعمل مثقالَ ذرّةٍ خيرًا يره ومن يعمل مثقالَ ذرّةٍ شرًّا يره؛ هل تُجزَون إلا ما كنتم تعملون؛ فالجزاءُ بقدرِ العملِ عدلًا؛ والصبرُ والجزعُ عند العذابِ لا ينفعان؛ فمن عمل صالحًا جُوزي خيرًا، ومن أساء جُوزي شرًّا؛ فاجعل العملَ الصالحَ سبيلَ جزائك الحسن."}}]},{"title":"نعيمُ المتّقين وإلحاقُ ذرّيّتهم بهم","range":[17,24],"theme":"أنّ المتّقين في جنّاتٍ ونعيمٍ فاكهين بما آتاهم ربّهم ووقاهم عذابَ الجحيم، يأكلون ويشربون هنيئًا متّكئين وزُوّجوا بحورٍ عين، وأنّ الذين آمنوا واتّبعتهم ذرّيّتهم بإيمانٍ أُلحِقت بهم ذرّيّتهم وكلُّ امرئٍ رهينٌ بعمله، ويُمَدّون بالفاكهةِ واللحمِ وكأسٍ لا لغوَ فيها ولا تأثيم ويطوف عليهم غلمانٌ كاللؤلؤ","verses":[{"n":17,"reflection":{"text":"«إن المتقين في جنات ونعيم»: إنّ المتّقين في بساتينَ ونعيمٍ مقيم؛ ففي هذا بيانُ جزاءِ المتّقين؛ فاطلب جنّاتِ المتّقين ونعيمها بالتقوى، فالجنّةُ والنعيمُ جزاءُ التقوى، فاعمل بالتقوى لتنالها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ جنّاتِ المتّقين ونعيمها بالتقوى."},"action":{"text":"تأمّل جزاءَ المتّقين: إنّ المتّقين الذين اتّقوا الله بفعلِ أوامره واجتنابِ نواهيه، في الآخرةِ في جنّاتٍ وبساتينَ عظيمة، ونعيمٍ مقيمٍ دائمٍ لا ينقطع؛ فبعد ذكرِ عذابِ المكذّبين، ذكر نعيمَ المتّقين مقابلةً وترغيبًا «إن المتقين في جنات ونعيم»؛ ففي هذا بيانُ جزاءِ المتّقين: الجنّاتُ والنعيمُ المقيم؛ فجزاؤهم بتقواهم الجنّةُ ونعيمها الدائم؛ فاطلب أنت جنّاتِ المتّقين ونعيمها بالتقوى؛ فالجنّةُ والنعيمُ جزاءُ أهلِ التقوى؛ إنّ للمتّقين مفازًا؛ إنّ المتّقين في مقامٍ أمين، في جنّاتٍ وعيون؛ فاعمل بالتقوى، فعلِ المأموراتِ وتركِ المحظورات، لتنال الجنّةَ والنعيم؛ فمن اتّقى نال الجنّةَ والنعيم، ومن فرّط حُرِمها؛ فاجعل التقوى سبيلك لنيلِ جنّاتِ المتّقين ونعيمها."}},{"n":18,"reflection":{"text":"«فاكهين بما آتاهم ربهم ووقاهم ربهم عذاب الجحيم»: متلذّذين بما أعطاهم ربّهم من النعيم، ووقاهم ربّهم عذابَ الجحيم؛ ففي هذا بيانُ كمالِ نعيمِ المتّقين: نعيمٌ ونجاةٌ من العذاب؛ فاطلب النعيمَ والنجاةَ من العذابِ بالتقوى، فجمعُ النعيمِ والوقايةِ تمامُ الفوز، فاعمل لهما.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ النعيمِ والنجاةِ من العذابِ بالتقوى."},"action":{"text":"تأمّل كمالَ نعيمِ المتّقين: المتّقون في الجنّةِ فاكهين، أي متلذّذين متنعّمين ناعمين فرحين، بما آتاهم وأعطاهم ربّهم من أصنافِ النعيمِ والكرامة؛ ووقاهم ربّهم برحمته عذابَ الجحيمِ ونجّاهم منه «فاكهين بما آتاهم ربهم ووقاهم ربهم عذاب الجحيم»؛ ففي هذا بيانُ كمالِ نعيمِ المتّقين: التلذّذُ بالنعيم، والوقايةُ من عذابِ الجحيم؛ فجمع لهم بين حصولِ النعيمِ والنجاةِ من العذاب؛ فاطلب أنت النعيمَ في الجنّةِ والنجاةَ من عذابِ الجحيمِ بالتقوى والعملِ الصالح؛ فجمعُ النعيمِ والوقايةِ من العذابِ تمامُ الفوز؛ فمن زُحزِح عن النارِ وأُدخِل الجنّةَ فقد فاز؛ فوقاهم الله شرَّ ذلك اليومِ ولقّاهم نضرةً وسرورًا؛ فاعمل بالتقوى لتنال النعيمَ وتنجو من العذاب؛ فمن اتّقى نال النعيمَ والنجاة، ومن فرّط خسرهما؛ فاجعل طلبَ النعيمِ والنجاةِ من العذابِ بالتقوى دأبك."}},{"n":19,"reflection":{"text":"«كلوا واشربوا هنيئا بما كنتم تعملون»: يُقال لهم: كلوا واشربوا هنيئًا مريئًا بسببِ ما كنتم تعملون في الدنيا؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ ثمرةُ العمل؛ فاعمل صالحًا لتأكل وتشرب هنيئًا في الجنّة، فالنعيمُ الهنيءُ جزاءُ العملِ الصالح، فاجعل العملَ الصالحَ دأبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ لنيلِ النعيمِ الهنيءِ في الجنّة."},"action":{"text":"تأمّل أنّ النعيمَ ثمرةُ العمل: يُقال للمتّقين في الجنّةِ إكرامًا وتلذيذًا: كلوا من طيّباتها واشربوا من شرابها هنيئًا مريئًا، لا تنغيصَ فيه ولا كدر؛ بسببِ ما كنتم تعملون في الدنيا من الإيمانِ والطاعةِ والعملِ الصالح «كلوا واشربوا هنيئا بما كنتم تعملون»؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ من الأكلِ والشربِ ثمرةُ العملِ الصالحِ في الدنيا؛ فبأعمالهم نالوا النعيمَ الهنيء؛ فاعمل أنت عملًا صالحًا لتأكل وتشرب هنيئًا مريئًا في الجنّة؛ كلوا واشربوا هنيئًا بما أسلفتم في الأيامِ الخالية؛ وتلك الجنّةُ التي أورثتموها بما كنتم تعملون؛ فالنعيمُ الهنيءُ في الجنّةِ جزاءُ العملِ الصالحِ والتقوى؛ فمن عمل صالحًا نال النعيمَ الهنيء، ومن فرّط حُرِمه؛ فاجعل العملَ الصالحَ سبيلَ نيلِ النعيمِ الهنيءِ في الجنّة."}},{"n":20,"reflection":{"text":"«متكئين على سرر مصفوفة وزوجناهم بحور عين»: متّكئين على سررٍ مصفوفةٍ متقابلة، وزوّجناهم بحورٍ عينٍ حسانٍ واسعاتِ العيون؛ ففي هذا بيانُ تمامِ نعيمِ الجنّة؛ فاطلب هذا النعيمَ الكاملَ بالعملِ الصالح، فنعيمُ الجنّةِ كاملٌ من راحةٍ وأنسٍ وأزواجٍ طاهرات، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الكامل: الراحةِ والأنسِ والأزواجِ الطاهرات."},"action":{"text":"تأمّل تمامَ نعيمِ الجنّة: المتّقون في الجنّةِ متّكئين، أي جالسين جلوسَ الراحةِ والطمأنينة، على سررٍ مصفوفةٍ مرتّبةٍ متقابلة؛ وزوّجناهم، قرنّاهم، بحورٍ عينٍ: نساءٍ بيضٍ حسانٍ واسعاتِ العيونِ جميلاتها، طاهرات «متكئين على سرر مصفوفة وزوجناهم بحور عين»؛ ففي هذا بيانُ تمامِ نعيمِ الجنّة: الراحةُ على السررِ المصفوفة، والأنسُ بالتقابل، والأزواجُ من الحورِ العين؛ فاطلب أنت هذا النعيمَ الكاملَ بالعملِ الصالحِ والتقوى؛ على سررٍ موضونةٍ متّكئين عليها متقابلين؛ وحورٌ عينٌ كأمثالِ اللؤلؤِ المكنون؛ فنعيمُ الجنّةِ كاملٌ من راحةٍ وأنسٍ وأزواجٍ طاهراتٍ ولذّة؛ فمن عمل صالحًا نال هذا النعيمَ الكامل، ومن فرّط حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الكاملِ دأبك."}},{"n":21,"reflection":{"text":"«والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم وما ألتناهم من عملهم من شيء كل امرئ بما كسب رهين»، والذين آمنوا واتّبعتهم ذرّيّتهم بإيمانٍ، ألحقنا بهم ذرّيّتهم في الجنّةِ (وإن قصر عملهم) إكرامًا للآباء، وما نقصنا الآباءَ من عملهم شيئًا، كلُّ امرئٍ رهينٌ بعمله؛ ففي هذا بيانُ فضلِ الله بإلحاقِ الذرّيةِ المؤمنة؛ فاحرص على إيمانِ ذرّيتك ليجتمعوا معك في الجنّة، واعلم أنك رهينٌ بعملك، فاعمل واحرص على صلاحِ أهلك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على إيمانِ الذرّية، وإدراكُ أنّ كلَّ نفسٍ رهينةٌ بعملها."},"action":{"text":"تأمّل فضلَ إلحاقِ الذرّية: والذين آمنوا بالله ورسوله، واتّبعتهم ذرّيّتهم بإيمانٍ (وإن لم يبلغوا درجةَ آبائهم في العمل)؛ ألحقنا بهم ذرّيّتهم في الجنّةِ ودرجاتها إكرامًا للآباء وقرّةً لأعينهم؛ وما ألتناهم، أي ما نقصنا الآباءَ، من عملهم وثوابهم شيئًا بسببِ رفعِ الذرّية؛ كلُّ امرئٍ بما كسب من عملٍ رهينٌ مرتهنٌ محاسب «والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم وما ألتناهم من عملهم من شيء كل امرئ بما كسب رهين»؛ ففي هذا بيانُ فضلِ الله بإلحاقِ الذرّيةِ المؤمنةِ بآبائهم في الجنّة، دون نقصٍ من عملِ الآباء، وأنّ كلَّ نفسٍ رهينةٌ بعملها؛ فأكرم الله الآباءَ بجمعِ ذرّيّتهم المؤمنةِ معهم؛ فاحرص أنت على إيمانِ ذرّيتك وتربيتهم على الدين، ليجتمعوا معك في الجنّة؛ ربّنا هب لنا من أزواجنا وذرّيّاتنا قرّةَ أعين؛ والذين آمنوا وعملوا الصالحاتِ ألحقنا بهم ذرّيّتهم؛ واعلم أنك رهينٌ بعملك، محاسبٌ عليه؛ كلُّ نفسٍ بما كسبت رهينة؛ فاعمل صالحًا، واحرص على صلاحِ أهلك وذرّيتك؛ فمن آمن وأصلح ذرّيته اجتمعوا في الجنّة؛ فاجعل الحرصَ على إيمانِ ذرّيتك وإدراكَ أنك رهينٌ بعملك دأبك."},"qadiyya":{"title":"قضيّةُ عدلٍ لا يُقابله عدل: لماذا لم يُلحَق أبناءُ أهل النار بآبائهم؟","question":"قال الله في أهل الجنّة: «**والذين آمنوا واتّبعتهم ذرّيّتُهم بإيمانٍ ألحقنا بهم ذرّيّتَهم، وما ألتناهم من عملهم من شيء**»، **ثمّ ختم**: «**كلُّ امرئٍ بما كسب رهين**».\n**فالذرّيّةُ تُرفع إلى منازل الآباء وإن لم تبلغها بعملها.**\n**وها هنا يخطر سؤالٌ لا بدّ منه**: **فهل يجري مثلُ هذا في الجهة الأخرى؟ أيُلحَق أبناءُ أهل النار بآبائهم؟**\nفالقضيّة: **ما جوابُ هذا الوهم؟ وعلى أيّ أصلٍ بُني؟** ثمّ: **ما موقع ﴿كلُّ امرئٍ بما كسب رهين﴾ من الآية؟**","background":"ولا يظهر موضعُ السؤال حتى نلاحظ ما وقع في الآية:\n**فقد أُعطي قومٌ ما لم يبلغوه بعملهم.**\n**وهذه زيادةٌ على المستحقّ.**\n**فإذا جاز أن يُزاد أحدٌ فوق عمله في جهة الخير، فقياسُ الطرد أن يُزاد في جهة الشرّ.**\n**والقياسُ ها هنا فاسد، ولكنّ فسادَه لا يظهر إلّا ببيان أنّ الدارين ليستا على أصلٍ واحد.**\n**فمن لم يعرف هذا الأصل وقع في الوهم، أو ظنّ في الآية اضطرابًا.**","what_happened":"**بيّن السعديُّ أوّلًا أنّ الإلحاق من تمام النعيم**: «**وهذا من تمام نعيم أهل الجنّة، أن ألحق اللهُ**... **ذرّيّتَهم الذين اتّبعوهم بإيمان**».\n**ثمّ فسّر الاتّباع**: «**أي: الذين لحقوهم بالإيمان الصادر من آبائهم، فصارت الذرّيّةُ تبعًا لهم بالإيمان**».\n**⭐ ثمّ زاد بقياس الأولى**: «**ومن باب أولى إذا تبعتهم ذرّيّتُهم بإيمانهم الصادر منهم أنفسهم**».\n**⭐ ثمّ قرّر الإلحاق ونفى النقص**: «**فهؤلاء المذكورون يلحقهم اللهُ بمنازل آبائهم في الجنّة وإن لم يبلغوها، جزاءً لآبائهم، وزيادةً في ثوابهم**»، **ثمّ: «ومع ذلك، لا ينقص اللهُ الآباءَ من أعمالهم شيئًا**».\n**⭐ ثمّ أورد الوهمَ بنفسه**: «**ولمّا كان ربّما توهّم متوهّمٌ أنّ أهل النار كذلك، يلحق اللهُ بهم أبناءهم وذرّيّتهم**».\n**⭐ ثمّ أجاب بالأصل الفارق**: «**أخبر أنّه ليس حكمُ الدارين حكمًا واحدًا، فإنّ النار دارُ العدل، ومن عدله تعالى أن لا يُعذّب أحدًا إلّا بذنب**».\n**ثمّ فسّر الختام**: «**أي: مرتهنٌ بعمله، فلا تزر وازرةٌ وزرَ أخرى، ولا يُحمل على أحدٍ ذنبُ أحد**».\n**⭐ ثمّ نصّ على وظيفة الجملة الأخيرة في نظم الآية**: «**هذا اعتراضٌ من فوائده إزالةُ الوهم المذكور**».","the_verdict":"**فالحاصلُ أنّ الآية أعطت في جهةٍ ما لم تُعطِ مثلَه في الجهة الأخرى، وأنّ ذلك ليس اضطرابًا بل هو مقتضى الأصل.**\n**⭐ والأصلُ الذي صاغه الإمامُ في جملةٍ واحدة**: «**ليس حكمُ الدارين حكمًا واحدًا، فإنّ النار دارُ العدل**».\n**فالعدلُ ألّا يُعذَّب أحدٌ إلّا بذنبٍ اقترفه؛ فلا زيادةَ في العقوبة على قدر الجرم، ولا تحميلَ لأحدٍ وزرَ غيره.**\n**وأمّا الجنّةُ فبابُ الفضل مفتوحٌ فيها؛ فيجوز أن يُعطى العبدُ فوق عمله، لأنّ الزيادة في الإحسان لا يُظلم بها أحد.**\n**فالفرقُ ليس تحكّمًا؛ إنّه لازمُ الفرق بين الفضل والعدل.**\n**⭐ ولهذا كان الجوابُ عن السؤال أن يُقال: نعم، يُزاد في جهة الخير ولا يُزاد في جهة الشرّ؛ والسببُ أنّ الزيادة في الأولى إحسانٌ إلى الجميع، وفي الثانية ظلمٌ للمزيد عليه.**\n**⭐ وأمّا قولُه «ومع ذلك لا ينقص اللهُ الآباءَ من أعمالهم شيئًا» فرفعٌ لوهمٍ آخر**: **أن يُظنّ أنّ رفعَ الأبناء يكون على حساب الآباء، كأنّ الثواب مقدارٌ محدودٌ يُقسم.**\n**فبُيّن أنّ الأبناء رُفعوا والآباءُ لم يُنقصوا؛ فليس في خزائن الله ضيق.**\n**⭐ وأمّا صنيعُ الإمام في إيراد الوهم فهو الذي تكرّر في هذا المشروع مرارًا**: **أن يُورد الإشكالَ على النصّ قبل أن يُورده غيرُه.**\n**بل زاد ها هنا شيئًا: أنّه بيّن أنّ القرآن نفسَه أورده ودفعه؛ فقال في الجملة الأخيرة: «هذا اعتراضٌ من فوائده إزالةُ الوهم المذكور».**\n**فجعل ﴿كلُّ امرئٍ بما كسب رهين﴾ مسوقةً لدفع ما قد يُتوهّم من التي قبلها.**\n**وهذا نوعٌ من النظر في النظم: أن يُسأل عن كلّ جملةٍ: لماذا وُضعت ها هنا بعينها؟**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: فرّق بين بابين قبل أن تقيس.** **فقد يصحّ الحكم في جهة الفضل ولا يصحّ في جهة العدل.** **وأكثرُ الإشكالات التي تُورد على النصوص سببُها قياسُ بابٍ على باب لا يشاركه في العلّة.** **فاسأل: أهذا من باب الإحسان أم من باب الاستحقاق؟**\n**والثاني: لا تظنّ أنّ ما يناله غيرُك يُنقص منك.** **فقد رُفع الأبناءُ ولم يُنقص الآباء.** **وهذا معنًى ينفع في الدنيا كما ينفع في الآخرة؛ فإنّ أكثر الحسد مبناه على تصوّرٍ أنّ الخير مقدارٌ محدودٌ إن أخذه أحدٌ نقص من غيره.**\n**والثالث: اسأل عن موضع الجملة لا عن معناها فقط.** **فقد نصّ الإمامُ على أنّ ﴿كلُّ امرئٍ بما كسب رهين﴾ جاءت لدفع وهم.** **فإذا قرأتَ آيةً فاسأل: لماذا وُضعت بعد التي قبلها؟** **فكثيرٌ من المعاني لا يظهر إلّا من الموضع.**","grade":"ma'thur","source":"بيانُ السعديّ للإلحاق («وهذا من تمام نعيم أهل الجنة، أن ألحق الله»، «ذريتهم الذين اتبعوهم بإيمان»)، وقياسُه («ومن باب أولى إذا تبعتهم ذريتهم بإيمانهم الصادر منهم أنفسهم»)، وتقريرُه («فهؤلاء المذكورون، يلحقهم الله بمنازل آبائهم في الجنة وإن لم يبلغوها، جزاء لآبائهم، وزيادة في ثوابهم»، «ومع ذلك، لا ينقص الله الآباء من أعمالهم شيئا»)، وإيرادُه للوهم («ولما كان ربما توهم متوهم أن أهل النار كذلك، يلحق الله بهم أبناءهم وذريتهم»)، وجوابُه بالأصل الفارق («أخبر أنه ليس حكم الدارين حكما واحدا، فإن النار دار العدل، ومن عدله تعالى أن لا يعذب أحدا إلا بذنب»)، وتفسيرُه للختام («أي: مرتهن بعمله، فلا تزر وازرة وزر أخرى، ولا يحمل على أحد ذنب أحد»)، وتنصيصُه على وظيفة الجملة («هذا اعتراض من فوائده إزالة الوهم المذكور»): كلُّها بنصّها في تفسير السعديّ (٥٢:٢١).","honesty":"وممّا يجب أن يُقال:\n**بيانُنا في التمهيد لوجه القياس الفاسد، تمهيدٌ منّا لبيان موضع الوهم الذي أورده السعديُّ؛ وليس نصًّا له.**\n**وأمّا قولُنا إنّ الزيادة في جهة الخير إحسانٌ وفي جهة الشرّ ظلمٌ للمزيد عليه، فتحريرٌ منّا لمقتضى قوله «فإنّ النار دار العدل»؛ ومن رأى أنّا وسّعنا فليردّه.**\n**وأمّا قولُنا إنّ أكثر الحسد مبناه على تصوّر أنّ الخير مقدارٌ محدود، فوصفٌ منّا، لا نصٌّ له.**\n**ولم نتعرّض لمسائل شفاعة الآباء وأحكام أطفال المشركين**، وهي أبوابٌ لها أهلُها ومظانُّها.\n**ووقع في المطبوع من التفسير في هذا الموضع زيادةٌ بين معقوفتين، فصلنا اقتباسَنا عندها ولم نُدخلها في المنقول.**"}},{"n":22,"reflection":{"text":"«وأمددناهم بفاكهة ولحم مما يشتهون»، وأمددناهم بفاكهةٍ ولحمٍ ممّا يشتهون؛ ففي هذا بيانُ سعةِ نعيمِ الجنّة؛ فاطلب نعيمَ الجنّةِ الذي فيه ما تشتهي بالعملِ الصالح، فنعيمُ الجنّةِ يمدّهم الله به دائمًا، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الذي يمدُّ الله به أهلها."},"action":{"text":"تأمّل سعةَ نعيمِ الجنّة: وأمددنا المتّقين في الجنّةِ وزدناهم بفاكهةٍ كثيرةٍ متنوّعة، ولحمٍ ممّا يشتهونه ويتمنّونه من أطايبِ اللحوم؛ فيمدّهم الله بما يشتهون دائمًا بلا انقطاع «وأمددناهم بفاكهة ولحم مما يشتهون»؛ ففي هذا بيانُ سعةِ نعيمِ الجنّةِ ودوامه، حيث يمدّهم الله بالفاكهةِ واللحمِ ممّا يشتهون؛ فيزيدهم من النعيمِ ما يشتهون؛ فاطلب أنت نعيمَ الجنّةِ الذي فيه ما تشتهي الأنفس، بالعملِ الصالحِ والتقوى؛ ولحمِ طيرٍ ممّا يشتهون؛ وفاكهةٍ ممّا يتخيّرون؛ ولكم فيها ما تشتهي أنفسكم؛ فيها ما تشتهيه الأنفسُ وتلذُّ الأعين؛ فنعيمُ الجنّةِ يمدّهم الله به دائمًا بلا انقطاعٍ ولا نفاد؛ فمن عمل صالحًا نال هذا النعيم، ومن فرّط حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الذي يمدُّ الله به أهلها دأبك."}},{"n":23,"reflection":{"text":"«يتنازعون فيها كأسا لا لغو فيها ولا تأثيم»: يتعاطون في الجنّةِ كأسَ الخمرِ بلطفٍ، لا لغوَ فيها ولا إثم؛ ففي هذا بيانُ طهارةِ نعيمِ الجنّةِ من كلِّ نقص؛ فاطلب نعيمَ الجنّةِ الطاهرَ من كلِّ لغوٍ وإثم، فخمرُ الجنّةِ لذّةٌ بلا أذًى، فاعمل لهذا النعيمِ الطاهر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الطاهرِ من كلِّ لغوٍ وإثم."},"action":{"text":"تأمّل طهارةَ نعيمِ الجنّة: يتنازع المتّقون في الجنّةِ ويتعاطون بينهم كأسَ الخمرِ بلطفٍ وأنسٍ وسرور؛ لا لغوَ فيها، أي لا باطلَ ولا كلامَ ساقطٌ يصدر عن شاربها؛ ولا تأثيمَ، أي لا إثمَ ولا ذنبَ يلحقهم بسببها، بخلافِ خمرِ الدنيا «يتنازعون فيها كأسا لا لغو فيها ولا تأثيم»؛ ففي هذا بيانُ طهارةِ نعيمِ الجنّةِ من كلِّ نقصٍ وأذًى؛ فخمرُ الجنّةِ لذّةٌ بلا لغوٍ ولا إثمٍ ولا صداعٍ ولا سُكر؛ فاطلب أنت نعيمَ الجنّةِ الطاهرَ من كلِّ لغوٍ وإثمٍ ونقصٍ بالعملِ الصالح؛ لا يُصدَّعون عنها ولا يُنزِفون؛ لا فيها غولٌ ولا هم عنها يُنزَفون؛ لا يسمعون فيها لغوًا ولا تأثيمًا إلا قيلًا سلامًا سلامًا؛ فنعيمُ الجنّةِ طاهرٌ كاملٌ لا نقصَ فيه ولا كدر؛ فمن عمل صالحًا نال هذا النعيمَ الطاهر، ومن فرّط حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الطاهرِ دأبك."}},{"n":24,"reflection":{"text":"«ويطوف عليهم غلمان لهم كأنهم لؤلؤ مكنون»، ويطوف على المتّقين خدمٌ لهم كأنهم في الحسنِ والصفاءِ لؤلؤٌ مصونٌ مكنون؛ ففي هذا بيانُ تمامِ خدمةِ أهلِ الجنّة؛ فاطلب هذا النعيمَ الكاملَ بالعملِ الصالح، فأهلُ الجنّةِ يُخدَمون أتمَّ خدمة، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ وخدمتها الكاملة."},"action":{"text":"تأمّل تمامَ خدمةِ أهلِ الجنّة: ويطوف على المتّقين للخدمةِ غلمانٌ ووِلدانٌ مخصّصون لهم، كأنهم في حسنهم وصفائهم وبياضهم لؤلؤٌ مكنونٌ مصونٌ في صدفه لم تمسّه الأيدي «ويطوف عليهم غلمان لهم كأنهم لؤلؤ مكنون»؛ ففي هذا بيانُ تمامِ خدمةِ أهلِ الجنّة، حيث يطوف عليهم غلمانٌ حسانٌ كاللؤلؤِ المكنون؛ فيُخدَمون أتمَّ خدمةٍ وأحسنها؛ فاطلب أنت هذا النعيمَ الكاملَ والخدمةَ التامّةَ بالعملِ الصالحِ والتقوى؛ ويطوف عليهم وِلدانٌ مخلّدون إذا رأيتهم حسبتهم لؤلؤًا منثورًا؛ فأهلُ الجنّةِ يُخدَمون ويُكرَمون أتمَّ إكرام؛ فمن عمل صالحًا نال هذا النعيمَ والخدمة، ومن فرّط حُرِمها؛ فاجعل العملَ لنعيمِ الجنّةِ وخدمتها الكاملةِ دأبك."}}]},{"title":"تذاكرُ أهلِ الجنّةِ سببَ نجاتهم","range":[25,28],"theme":"إقبالُ أهلِ الجنّةِ بعضهم على بعضٍ يتساءلون، فيذكرون أنهم كانوا في الدنيا مشفقين خائفين من عذابِ الله فمنَّ عليهم ووقاهم عذابَ السموم، وأنهم كانوا يدعونه فهو البرُّ الرحيم","verses":[{"n":25,"reflection":{"text":"«وأقبل بعضهم على بعض يتساءلون»، وأقبل أهلُ الجنّةِ بعضهم على بعضٍ يتساءلون عن أحوالهم في الدنيا؛ ففي هذا بيانُ أنسِ أهلِ الجنّةِ بالتذاكر؛ فاطلب أنسَ الجنّةِ ومجالسها الطيّبةَ بالعملِ الصالح، فأهلُ الجنّةِ في أنسٍ وتذاكرٍ لنعمِ الله، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لأنسِ الجنّةِ ومجالسها الطيّبة، وتذاكرِ نعمِ الله."},"action":{"text":"تأمّل أنسَ أهلِ الجنّة: وأقبل أهلُ الجنّةِ بعضهم على بعضٍ في مجالسهم يتساءلون ويتحدّثون عن أحوالهم في الدنيا، وما كانوا فيه، وكيف منَّ الله عليهم بالنجاةِ والنعيم «وأقبل بعضهم على بعض يتساءلون»؛ ففي هذا بيانُ أنسِ أهلِ الجنّةِ ومجالسهم الطيّبةِ التي يتذاكرون فيها نعمَ الله وأحوالهم؛ فيتساءلون تلذّذًا بذكرِ نعمِ الله ونجاتهم؛ فاطلب أنت أنسَ الجنّةِ ومجالسها الطيّبةَ بالعملِ الصالحِ والتقوى؛ إخوانًا على سررٍ متقابلين؛ وأقبل بعضهم على بعضٍ يتساءلون، قال قائلٌ منهم إني كان لي قرين؛ فأهلُ الجنّةِ في أنسٍ ومحبّةٍ وتذاكرٍ لنعمِ الله وفضله؛ فمن عمل صالحًا نال أنسَ الجنّةِ ومجالسها، ومن فرّط حُرِمها؛ فاجعل العملَ لأنسِ الجنّةِ وتذاكرِ نعمِ الله دأبك."}},{"n":26,"reflection":{"text":"«قالوا إنا كنا قبل في أهلنا مشفقين»: قالوا: إنا كنّا قبلُ في الدنيا في أهلنا خائفين من عذابِ الله؛ ففي هذا بيانُ أنّ الخوفَ في الدنيا سببُ الأمنِ في الآخرة؛ فاخشَ الله في الدنيا لتأمن في الآخرة، فالخوفُ من الله يورث النجاة، فاجعل الخشيةَ دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"خشيةُ الله في الدنيا لنيلِ الأمنِ في الآخرة."},"action":{"text":"تأمّل أنّ الخوفَ سببُ الأمن: قال أهلُ الجنّةِ يتذاكرون سببَ نجاتهم: إنا كنّا قبلُ في الدنيا، ونحن في أهلنا وبين ذوينا، مشفقين، أي خائفين وجلين من عذابِ الله، حذرين من معصيته، مهتمّين بأمرِ آخرتنا «قالوا إنا كنا قبل في أهلنا مشفقين»؛ ففي هذا بيانُ أنّ سببَ نجاةِ أهلِ الجنّةِ خوفهم وإشفاقهم من عذابِ الله في الدنيا؛ فبخوفهم في الدنيا أمِنوا في الآخرة؛ فاخشَ أنت الله في الدنيا وأشفق من عذابه لتأمن في الآخرة؛ والذين هم من عذابِ ربّهم مشفقون؛ إنّا كنّا قبلُ في أهلنا مشفقين؛ إنّ الذين هم من خشيةِ ربّهم مشفقون؛ ومن خاف مقامَ ربّه جنّتان؛ فالخوفُ من الله والإشفاقُ من عذابه يورثان الأمنَ والنجاةَ في الآخرة؛ فمن خاف الله في الدنيا أمِن في الآخرة، ومن أمِن في الدنيا خاف في الآخرة؛ فاجعل خشيةَ الله والإشفاقَ من عذابه في الدنيا دأبك."}},{"n":27,"reflection":{"text":"«فمن الله علينا ووقانا عذاب السموم»: فمنَّ الله علينا بفضله فوقانا عذابَ النارِ الحارّة النافذة؛ ففي هذا بيانُ أنّ النجاةَ بمنّةِ الله وفضله؛ فاعلم أنّ نجاتك بفضلِ الله لا بعملك وحده، فاشكر فضله وارجُ رحمته، فالنجاةُ منّةٌ من الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نسبةُ النجاةِ لفضلِ الله، وشكرُه ورجاءُ رحمته."},"action":{"text":"تأمّل أنّ النجاةَ بمنّةِ الله: قال أهلُ الجنّة: فمنَّ الله علينا بفضله ورحمته، فوفّقنا للإيمانِ والتقوى، ووقانا وحمانا عذابَ السمومِ، وهي النارُ الحارّةُ النافذةُ في المسامّ، أو ريحُ النارِ الحارّة «فمن الله علينا ووقانا عذاب السموم»؛ ففي هذا بيانُ أنّ أهلَ الجنّةِ نسبوا نجاتهم إلى منّةِ الله وفضله، لا إلى أعمالهم وحدها؛ فاعترفوا بأنّ النجاةَ بفضلِ الله؛ فاعلم أنت أنّ نجاتك ودخولك الجنّةَ بفضلِ الله ومنّته ورحمته، لا بعملك وحده؛ فلولا فضلُ الله عليكم ورحمته ما زكا منكم من أحد؛ لن يُدخِل أحدَكم عمله الجنّة، قالوا ولا أنت يا رسول الله، قال ولا أنا إلا أن يتغمّدني الله برحمة؛ فاشكر فضلَ الله ومنّته، وارجُ رحمته مع عملك؛ فالنجاةُ منّةٌ من الله وفضل؛ فمن نسب النجاةَ لفضلِ الله وشكره فاز، ومن أُعجِب بعمله خُذِل؛ فاجعل نسبةَ النجاةِ لفضلِ الله وشكرَه ورجاءَ رحمته دأبك."}},{"n":28,"reflection":{"text":"«إنا كنا من قبل ندعوه إنه هو البر الرحيم»: إنا كنّا من قبلُ في الدنيا ندعوه ونعبده، إنه هو البرُّ الرحيم؛ ففي هذا بيانُ أنّ دوامَ الدعاءِ والعبادةِ سببُ النجاة؛ فداوم على دعاءِ الله وعبادته، فالله برٌّ رحيمٌ يجيب من دعاه، فاجعل الدعاءَ والعبادةَ دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المداومةُ على دعاءِ الله وعبادته، ورجاءُ برّه ورحمته."},"action":{"text":"تأمّل أنّ الدعاءَ سببُ النجاة: قال أهلُ الجنّة: إنا كنّا من قبلُ في الدنيا ندعوه ونعبده ونوحّده ونرجوه ونخشاه؛ إنه هو البرُّ، كثيرُ الإحسانِ والخير، الصادقُ في وعده، الرحيمُ بعباده؛ فأجاب دعاءنا ونجّانا «إنا كنا من قبل ندعوه إنه هو البر الرحيم»؛ ففي هذا بيانُ أنّ أهلَ الجنّةِ كانوا في الدنيا يدعون الله ويعبدونه، وأنّ ذلك سببُ نجاتهم؛ فبدوامِ دعائهم وعبادتهم نالوا برَّ الله ورحمته؛ فداوم أنت على دعاءِ الله وعبادته ورجائه وخشيته؛ ادعوني أستجب لكم؛ وإذا سألك عبادي عني فإني قريبٌ أجيب دعوةَ الداعِ إذا دعان؛ فالله برٌّ رحيمٌ كثيرُ الإحسان، يجيب من دعاه ويرحم من عبده؛ فارجُ برَّ الله ورحمته بدوامِ الدعاءِ والعبادة؛ فمن داوم على دعاءِ الله وعبادته نال برّه ورحمته ونجاته، ومن أعرض عنه خسر؛ فاجعل المداومةَ على دعاءِ الله وعبادته ورجاءَ برّه ورحمته دأبك."}}]},{"title":"التذكيرُ وتبرئةُ النبيّ، وانتظارُ المشركين","range":[29,34],"theme":"الأمرُ بالتذكيرِ وتبرئةُ النبيِّ من الكهانةِ والجنونِ والشعرِ، وحكايةُ تربّصهم به ريبَ المنونِ والردُّ بأنه معهم من المتربّصين، وأنّ ردّهم ليس عن عقلٍ بل طغيان، وأنهم زعموا اختلاقَه للقرآنِ فليأتوا بمثله إن صدقوا","verses":[{"n":29,"reflection":{"text":"«فذكر فما أنت بنعمت ربك بكاهن ولا مجنون»: فذكّر، يا محمدُ، بالقرآن، فما أنت بنعمةِ ربّك بكاهنٍ ولا مجنونٍ كما يزعمون؛ ففي هذا الأمرُ بالتذكيرِ وتبرئةُ النبيِّ ممّا رموه به؛ فذكّر بالحقِّ ولا يصدّنك أذى الناسِ وتهمهم، فالتذكيرُ واجب، والتهمُ الباطلةُ لا تضرّ الحق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكيرُ بالحقِّ دون التفاتٍ للتهم، وإدراكُ نعمةِ الله على النبيّ."},"action":{"text":"تأمّل الأمرَ بالتذكير: فذكّر، يا محمدُ، الناسَ بالقرآنِ والمواعظِ ولا تبالِ بتكذيبهم؛ فما أنت بنعمةِ ربّك عليك بالنبوّةِ والعقلِ والرشدِ بكاهنٍ يأتيه الجنُّ بالأخبار، ولا مجنونٍ زائلِ العقلِ كما يزعم المكذّبون «فذكر فما أنت بنعمت ربك بكاهن ولا مجنون»؛ ففي هذا الأمرُ للنبيِّ بالتذكير، وتبرئتُه ممّا رماه به المشركون من الكهانةِ والجنون؛ فبرّأه الله ممّا اتّهموه به؛ فذكّر أنت بالحقِّ ولا يصدّنك أذى الناسِ وتهمهم الباطلة؛ فالتذكيرُ بالحقِّ واجبٌ لا يُترَك لأجلِ التهم؛ وذكّر فإنّ الذكرى تنفع المؤمنين؛ فادعُ إلى سبيلِ ربّك؛ والتهمُ الباطلةُ التي يرمى بها أهلُ الحقِّ لا تضرّ الحقَّ ولا تنقصه؛ فمن ذكّر بالحقِّ ولم يبالِ بالتهمِ أدّى ما عليه؛ فاجعل التذكيرَ بالحقِّ دون التفاتٍ للتهمِ الباطلةِ دأبك."}},{"n":30,"reflection":{"text":"«أم يقولون شاعر نتربص به ريب المنون»: بل أيقولون: هو شاعرٌ ننتظر به حوادثَ الدهرِ (الموت)؟ ففي هذا حكايةُ قولهم وانتظارهم موتَ النبيّ؛ فاحذر انتظارَ زوالِ الحقِّ وأهله، فالحقُّ باقٍ منصور، فلا تعلّق أملك على زوالِ أهلِ الحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ بقاءِ الحق، وتركُ انتظارِ زوالِ أهله."},"action":{"text":"تأمّل حكايةَ قولهم: بل أيقول المشركون في محمدٍ: هو شاعرٌ، نتربّص وننتظر به ريبَ المنون، أي حوادثَ الدهرِ ونوائبه، وأن يموت فنستريح منه ومن دعوته «أم يقولون شاعر نتربص به ريب المنون»؛ ففي هذا حكايةُ قولِ المشركين في النبيِّ إنه شاعر، وانتظارهم موته ليزول أمره؛ فتمنّوا موته وزوالَ دعوته؛ فاحذر أنت انتظارَ زوالِ الحقِّ وأهله كما فعل المشركون؛ فالحقُّ باقٍ منصورٌ لا يزول بموتِ أهله؛ وما محمدٌ إلا رسولٌ قد خلت من قبله الرسل، أفإن مات أو قُتِل انقلبتم على أعقابكم؛ فالدينُ باقٍ والحقُّ ظاهرٌ ولو مات حَمَلته؛ يريدون ليطفئوا نورَ الله بأفواههم والله متمُّ نوره؛ فلا تعلّق أملك على زوالِ أهلِ الحقِّ فالحقُّ باقٍ؛ فمن أدرك بقاءَ الحقِّ ثبت، ومن انتظر زواله خاب؛ فاجعل إدراكَ بقاءِ الحقِّ وتركَ انتظارِ زوالِ أهله دأبك."}},{"n":31,"reflection":{"text":"«قل تربصوا فإني معكم من المتربصين»: قل: تربّصوا وانتظروا، فإني معكم من المنتظرين لما يحلُّ بكم؛ ففي هذا تحدٍّ لهم بانتظارِ عاقبةِ الحق؛ فاثق بأنّ العاقبةَ للحقِّ وأهله، فانتظر نصرَ الله، فالمنتظِر لنصرِ الله فائز، والمنتظِر لزوالِ الحقِّ خائب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ العاقبةَ للحقّ، وانتظارُ نصرِ الله."},"action":{"text":"تأمّل التحدّي بانتظارِ العاقبة: قل، يا محمدُ، لهؤلاء المتربّصين بك الموت: تربّصوا وانتظروا ما تريدون بي؛ فإني معكم من المتربّصين المنتظرين لما يحلُّ بكم من العذابِ والنصرِ عليكم؛ فسترون لمن تكون العاقبة «قل تربصوا فإني معكم من المتربصين»؛ ففي هذا تحدٍّ للمشركين بانتظارِ العاقبة، وثقةٌ بأنها للحقِّ وأهله؛ فأمرهم بالتربّصِ وأخبر أنه متربّصٌ معهم، والعاقبةُ له؛ فاثق أنت بأنّ العاقبةَ للحقِّ وأهله، وأنّ الله ناصرٌ دينه ورسله؛ وانتظر نصرَ الله ووعده؛ فارتقب إنهم مرتقبون؛ قل كلٌّ متربّصٌ فتربّصوا؛ إنّ العاقبةَ للمتّقين؛ إنّا لننصر رسلنا والذين آمنوا؛ فالمنتظِرُ لنصرِ الله وعاقبةِ الحقِّ فائز، والمنتظِرُ لزوالِ الحقِّ خائب؛ فمن وثق بالعاقبةِ للحقِّ وانتظر نصرَ الله فاز، ومن انتظر زوالَ الحقِّ خاب؛ فاجعل الثقةَ بأنّ العاقبةَ للحقِّ وانتظارَ نصرِ الله دأبك."}},{"n":32,"reflection":{"text":"«أم تأمرهم أحلامهم بهذا أم هم قوم طاغون»: بل أتأمرهم عقولهم بهذا التناقضِ (وصفِه بالشاعرِ والكاهنِ والمجنون)؟ بل هم قومٌ طاغون؛ ففي هذا بيانُ أنّ تكذيبهم طغيانٌ لا عقل؛ فاعلم أنّ ردَّ الحقِّ طغيانٌ لا عقل، فحكّم عقلك في اتّباعِ الحقّ، فالطغيانُ يعمي عن الحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحكيمُ العقلِ في اتّباعِ الحق، وإدراكُ أنّ ردَّه طغيان."},"action":{"text":"تأمّل أنّ تكذيبهم طغيان: بل أتأمرهم عقولهم وأحلامهم بهذا القولِ المتناقض في محمد (شاعرٌ وكاهنٌ ومجنون، وهي أوصافٌ متناقضة)؟ لا، فالعقلُ لا يأمر بهذا التناقض؛ بل هم قومٌ طاغون متجاوزون الحدَّ في الكفرِ والعناد، فحملهم الطغيانُ على ذلك «أم تأمرهم أحلامهم بهذا أم هم قوم طاغون»؛ ففي هذا بيانُ أنّ تكذيبَ المشركين ووصفهم المتناقضَ للنبيِّ ليس عن عقلٍ ولا حجّة، بل عن طغيانٍ وعناد؛ فالطغيانُ حملهم على ذلك، لا العقل؛ فاعلم أنت أنّ ردَّ الحقِّ ووصفه بالباطلِ طغيانٌ لا عقل؛ فالعقلُ السليمُ يقبل الحقَّ الواضح؛ فحكّم أنت عقلك في اتّباعِ الحقِّ وقبوله؛ إنّ شرَّ الدوابِّ عند الله الصمُّ البكمُ الذين لا يعقلون؛ أفلا يتدبّرون القرآن؛ فالطغيانُ والعنادُ يعميان عن الحقِّ ويحملان على ردّه؛ فمن حكّم عقله في قبولِ الحقِّ اهتدى، ومن طغى وعاند ضلّ؛ فاجعل تحكيمَ العقلِ في اتّباعِ الحقِّ دأبك."}},{"n":33,"reflection":{"text":"«أم يقولون تقوله بل لا يؤمنون»: بل أيقولون: اختلق محمدٌ القرآنَ من عند نفسه؟ بل هم لا يؤمنون؛ ففي هذا بيانُ أنّ سببَ تكذيبهم عدمُ الإيمانِ لا شبهةٌ حقيقية؛ فاعلم أنّ ردَّ الحقِّ سببه غالبًا عدمُ الإيمانِ لا الحجّة، فأخلص نيّتك في طلبِ الحقِّ لتؤمن به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في طلبِ الحق، وإدراكُ أنّ ردَّه سببه عدمُ الإيمان."},"action":{"text":"تأمّل سببَ تكذيبهم: بل أيقول المشركون: تقوّل محمدٌ القرآنَ واختلقه من عند نفسه ونسبه إلى الله؟ ليس الأمرُ كذلك؛ بل هم لا يؤمنون، فتكذيبهم ليس عن شبهةٍ حقيقية، بل عن استكبارٍ وعدمِ إيمان «أم يقولون تقوله بل لا يؤمنون»؛ ففي هذا بيانُ أنّ سببَ تكذيبِ المشركين ودعواهم أنّ النبيَّ اختلق القرآن، ليس شبهةً حقيقية، بل عدمُ الإيمانِ والاستكبار؛ فلو أرادوا الحقَّ لآمنوا؛ فاعلم أنت أنّ ردَّ الحقِّ سببه غالبًا عدمُ الإيمانِ والإخلاصِ في طلبه، لا الحجّةُ والشبهة؛ فمن طلب الحقَّ بإخلاصٍ وجده وآمن به؛ ومن أعرض بلا حجّةٍ فسببه عدمُ الإيمان؛ والذين جاهدوا فينا لنهدينّهم سبلنا؛ فأخلص أنت نيّتك في طلبِ الحقِّ لتؤمن به وتنتفع؛ فمن أخلص في طلبِ الحقِّ آمن به، ومن أعرض عنه لعدمِ إيمانه خسر؛ فاجعل الإخلاصَ في طلبِ الحقِّ دأبك."}},{"n":34,"reflection":{"text":"«فليأتوا بحديث مثله إن كانوا صادقين»: فليأتوا بكلامٍ مثلِ القرآنِ إن كانوا صادقين في دعوى اختلاقه؛ ففي هذا تحدٍّ لهم بالإتيانِ بمثلِ القرآن؛ فاعلم أنّ عجزهم عن الإتيانِ بمثله دليلُ أنه من عند الله، فأيقن بأنّ القرآنَ كلامُ الله، فاعتزّ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ القرآنَ كلامُ الله، والاعتزازُ به."},"action":{"text":"تأمّل التحدّي بمثلِ القرآن: فليأتِ هؤلاء المشركون بحديثٍ وكلامٍ مثلِ هذا القرآنِ في بلاغته ونظمه وهدايته، إن كانوا صادقين في دعواهم أنّ محمدًا اختلقه من عند نفسه؛ فإنهم عربٌ فصحاء، فإن عجزوا فهو من عند الله «فليأتوا بحديث مثله إن كانوا صادقين»؛ ففي هذا تحدٍّ للمشركين بالإتيانِ بمثلِ القرآن، وإثباتٌ لعجزهم؛ فلمّا عجزوا مع فصاحتهم، ثبت أنه من عند الله لا من عند البشر؛ فاعلم أنت أنّ عجزَ الخلقِ عن الإتيانِ بمثلِ القرآنِ دليلٌ قاطعٌ على أنه كلامُ الله المعجز؛ قل لئنِ اجتمعتِ الإنسُ والجنُّ على أن يأتوا بمثلِ هذا القرآنِ لا يأتون بمثله ولو كان بعضهم لبعضٍ ظهيرًا؛ فأتوا بسورةٍ من مثله؛ فأيقن بأنّ القرآنَ كلامُ الله المعجز؛ واعتزّ به وعظّمه واتّبعه؛ فمن أيقن بأنّ القرآنَ كلامُ الله عظّمه واهتدى به؛ فاجعل اليقينَ بأنّ القرآنَ كلامُ الله والاعتزازَ به دأبك."}}]},{"title":"سلسلةُ الأسئلةِ التعجيزيةِ على المشركين","range":[35,43],"theme":"إقامةُ الحجّةِ بأنهم لم يُخلَقوا من غيرِ شيءٍ ولا خلقوا أنفسهم ولا السماواتِ والأرض، وليس عندهم خزائنُ الله ولا سلّمٌ يستمعون به الغيب، ولا لله البناتُ ولهم البنون، ولا يسألهم أجرًا، ولا عندهم الغيب، ولا كيدهم ينفعهم، ولا لهم إلهٌ غيرُ الله سبحانه عمّا يشركون","verses":[{"n":35,"reflection":{"text":"«أم خلقوا من غير شيء أم هم الخالقون»: أخُلِقوا من غيرِ خالقٍ خلقهم؟ أم هم خلقوا أنفسهم؟ ففي هذا حجّةٌ عقليةٌ قاطعةٌ على وجودِ الخالق؛ فأيقن بأنّ لك خالقًا خلقك، فلا بدّ للمخلوقِ من خالق، فوحّد الخالقَ الذي أوجدك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوجودِ الخالق، وتوحيدُه، وإدراكُ ضرورةِ الخالقِ للمخلوق."},"action":{"text":"تأمّل الحجّةَ العقلية: أخُلِق هؤلاء المشركون من غيرِ شيءٍ خلقهم، أي بلا خالقٍ أوجدهم؟ هذا محال؛ أم هم الخالقون لأنفسهم؟ وهذا أشدُّ استحالة؛ فلا بدّ من خالقٍ خلقهم، وهو الله «أم خلقوا من غير شيء أم هم الخالقون»؛ ففي هذا حجّةٌ عقليةٌ قاطعةٌ على وجودِ الخالق؛ فإمّا أن يكونوا خُلِقوا من غيرِ خالق (محال)، أو خلقوا أنفسهم (محال)، فتعيّن أنّ لهم خالقًا خلقهم وهو الله؛ فاعلم أنت أنّ لك خالقًا خلقك، فلا يُعقَل وجودُ مخلوقٍ بلا خالق؛ فلا بدّ للمخلوقِ من خالقٍ أوجده؛ فوحّد أنت الخالقَ الذي أوجدك من العدم؛ يا أيها الناس اعبدوا ربّكم الذي خلقكم؛ هل من خالقٍ غيرُ الله؛ فمن أيقن بأنّ له خالقًا وحّده وعبده، ومن جحد ضلّ؛ فاجعل اليقينَ بوجودِ الخالقِ وتوحيدَه دأبك."},"qadiyya":{"title":"قضيّةُ استفهامٍ ينحصر به الأمرُ في ثلاثة","question":"قال الله: ﴿أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخَالِقُونَ﴾.\nوظاهرُ اللفظ سؤالان في سياق تقريع، جاءا في نسقٍ من الاستفهامات المتتابعة في السورة، فيمرّ بهما القارئُ على أنّهما توبيخٌ للمكذّبين.\nفالقضيّة: **كيف يكون هذا الاستفهامُ استدلالًا لا تقريعًا؟** ثمّ: **الآيةُ ذكرت قسمين، فمن أين جاء الثالث، وبأيّ شيءٍ انحصرت الأقسام؟** ثمّ: **ما وجهُ انتقال الحجّة من الخلق إلى العبادة؟**","background":"وقبل الجواب أمران.\nالأوّل: أنّ من طرق الحجاج أن تُحصر الاحتمالاتُ في المسألة، ثمّ يُبطَل منها واحدٌ بعد واحد حتّى لا يبقى إلّا واحد، فيتعيّن. وقوّتُه على شرطين: **أن تكون القسمة حاصرةً لا يشذّ عنها احتمال، وأن يكون إبطالُ ما أُبطل قاطعًا لا مرجوحًا.**\nوالثاني: حالُ المخاطبين، وقد وصفهم الإمامُ بأنّهم «منكرون لتوحيد الله، مكذبون لرسوله». وهم مع ذلك مقرّون بأنّهم موجودون؛ فليست الخصومةُ في أنّهم كائنون، بل في الجهة التي منها صاروا كائنين.","what_happened":"**سمّى السعديُّ الآية استدلالًا قبل أن يشرحها**: «وهذا استدلال عليهم، بأمر لا يمكنهم فيه إلا التسليم للحق، أو الخروج عن موجب العقل والدين».\nثمّ بيّن موضع الخصم: «وبيان ذلك: أنهم منكرون لتوحيد الله، مكذبون لرسوله، وذلك مستلزم لإنكار أن الله خلقهم».\n⭐ ثمّ قرّر الحصر وعدّ الأقسام: «وقد تقرر في العقل مع الشرع، أن الأمر لا يخلو من أحد ثلاثة أمور».\nثمّ ساق الأوّل وحكم عليه: «إما أنهم خلقوا من غير شيء أي: لا خالق خلقهم، بل وجدوا من غير إيجاد ولا موجد، وهذا عين المحال».\nثمّ ساق الثاني وحكم عليه وعلّل حكمه: «أم هم الخالقون لأنفسهم، وهذا أيضا محال، فإنه لا يتصور أن يوجدوا أنفسهم».\n⭐ ثمّ رتّب النتيجة على البطلان فقال: «وبان استحالتهما، تعين»، وفي المطبوع ها هنا زيادةٌ بين معقوفتين تسمّي الثالث، ثمّ يتّصل كلامُه: «أن الله الذي خلقهم، وإذا تعين ذلك، علم أن الله تعالى هو المعبود وحده».\nوقال في آخر السياق عند قوله ﴿أَمْ لَهُمْ إِلَٰهٌ غَيْرُ اللَّهِ﴾: «وهذا هو المقصود من الكلام الذي سيق لأجله، وهو بطلان عبادة ما سوى الله وبيان فسادها بتلك الأدلة القاطعة».","the_verdict":"فالحاصلُ أنّ الآية حجّةٌ مبنيّة، لا موعظةً مساقة.\n⭐ وموضعُ إحكامها أنّ مقدّمتها هي المخاطَبُ نفسُه. فلم يُطلب منه أن يسلّم بخبرٍ عن غائب، بل أن يجيب من أين جاء؛ وليس بين يديه إلّا أن يقول: وُجدتُ بلا موجِد، أو أوجدتُ نفسي، أو أوجدني غيري. ولذلك قال الإمامُ إنّه أمرٌ لا يمكنهم فيه إلّا «التسليم للحق، أو الخروج عن موجب العقل والدين»؛ والذي يظهر لنا أنّ المخرج المُبقى لهم ليس نقضَ الحجّة، بل الخروجَ عمّا يوجبه العقلُ والدينُ جميعًا.\nوأمّا الثالث فقد نصّ الإمامُ على أنّ الأقسام ثلاثة، ثمّ سمّاه في موضع النتيجة لا في موضع العدّ. والذي يظهر لنا أنّ السكوت عنه في اللفظ من تمام الحجّة: **فإنّ القسمة إذا كانت حاصرة كان إبطالُ القسمين تعيينًا للثالث بغير ذكره**، فيقوله الخصمُ من عند نفسه.\nوأمّا حصرُها فلأنّ الموجود إمّا أن يكون له موجِدٌ أو لا يكون؛ فإن لم يكن فهو الأوّل، وإن كان فإمّا هو نفسُه وإمّا غيرُه. **فالقسمة دائرةٌ بين النفي والإثبات**، فلم يبقَ لرابعٍ موضع.\n⭐ وقد علّل الإمامُ استحالة الثاني بامتناع التصوّر، ووجهُه عندنا أنّ الموجِد سابقٌ على الموجَد، فمن أوجد نفسَه كان موجودًا قبل أن يوجد. وأمّا الأوّل فأرسل الحكمَ عليه ولم يزد؛ ووجهُه عندنا أنّ ما لم يكن ثمّ كان لا يستغني عن موجِد.\nوأمّا الانتقال إلى العبادة فربطه الإمامُ بالشرط: «وإذا تعين ذلك، علم أن الله تعالى هو المعبود وحده». وقد ذكر أنّ إنكار التوحيد مستلزمٌ لإنكار أن الله خلقهم؛ فلمّا ثبت الخلقُ سقط ما بُني على نفيه، وإليه انتهى السياقُ عنده.\nوأمّا الغلط فوجهان: أن تُقرأ الآيةُ تقريعًا فيُمرّ بها، وقد جعلها الإمامُ استدلالًا؛ وأن يُظنّ أنّ الخصومة تنقطع بالحشد، وإنّما تنقطع بأن يكون كلُّ دليلٍ مسدودَ المخرج؛ ولذلك تتابعت في السورة أدلّةٌ وصفها الإمامُ بأنّها «الأدلة القاطعة».","for_you":"فأمّا الذي تخرج به فثلاثة.\n**الأوّل: عُدَّ الاحتمالات قبل أن تجيب.** فإذا نزلت بك خصومة، فاكتب الاحتمالات الممكنة، ثمّ اشطب ما تقوم على بطلانه حجّة. فإن بقي واحدٌ فهو الجواب، وإن بقي اثنان فلم تفرغ بعد. والاختبار أن ينظر في المكتوب غيرُك.\n**والثاني: ابدأ من مقدّمةٍ يسلّمها مخالفُك.** فانظر في أوّل جملةٍ تسوقها، ثمّ اسأل: أيقرّ بها من تحاجّه؟ فإن كان ينكرها فقد بنيتَ على ما لا يقوم، فانزل عنها إلى ما دونها حتّى تبلغ ما لا يملك دفعه.\n**والثالث: حوّل الاستفهام إلى خبر.** فاجعل كلّ سؤالٍ من الاستفهامات المتتابعة في السورة جملةً خبريّةً على مقتضى الإنكار، ثمّ انظر ماذا بقي بعدها.","grade":"ma'thur","source":"وصفُ الآية بأنّها استدلال («وهذا استدلال عليهم، بأمر لا يمكنهم فيه»)، ولازمُ إنكارهم («وبيان ذلك: أنهم منكرون لتوحيد الله»)، وتقريرُ الحصر في ثلاثة («وقد تقرر في العقل مع الشرع»)، والقسمان والحكمُ عليهما («إما أنهم خلقوا من غير شيء»، «أم هم الخالقون لأنفسهم»)، وترتيبُ النتيجة والتوحيد عليها («وبان استحالتهما، تعين»): كلُّها بنصّها في تفسير السعديّ (٥٢:٣٥). ومقصودُ السياق ووصفُ الأدلّة («وهذا هو المقصود من الكلام») في (٥٢:٤٣).","honesty":"وممّا يجب أن يُقال:\nتقريرُ طريق الحصر واشتراطُنا فيه شرطين، وقولُنا إنّ المخاطبين مقرّون بوجودهم وإنّما الخصومة في جهة صيرورتهم، تمهيدٌ منّا لا نصًّا للإمام. وكذلك حملُنا الاستفهام على الإنكار والنفي، فإنّه إنّما نصّ على تقرير النفي في الآية التي بعدها.\nوأمّا تسميتُنا مقدّمةَ الحجّة المخاطَبَ نفسَه، وقولُنا إنّ المخرج المُبقى لهم هو الخروج عمّا يوجبه العقل والدين، فتعبيرٌ منّا عن مقتضى كلامه لا لفظُه.\nوأمّا تعليلُنا استحالة القسمين فاستنباطٌ منّا؛ والذي له أنّه علّل الثاني بامتناع التصوّر، وأرسل الحكم على الأوّل ولم يزد.\nوأمّا قولُنا إنّ السكوت عن الثالث من تمام الحجّة، وردُّنا الأقسامَ إلى دورانها بين النفي والإثبات، فاستنباطٌ وترتيبٌ منّا؛ والذي له عدُّها ثلاثةً وتقريرُ أنّ الأمر لا يخلو منها.\nوأمّا قولُنا إنّ ثبوت الخلق يُسقط ما بُني على نفيه، فترتيبٌ منّا على لزومٍ ذكره من الجهة الأخرى، وهو أنّ إنكار التوحيد مستلزمٌ لإنكار الخلق.\nوأمّا وجها الغلط، والثلاثةُ التي يُعمل بها، فتخريجٌ منّا وأمثلةٌ من عندنا. ومن رأى أنّا وسّعنا فليردّه."}},{"n":36,"reflection":{"text":"«أم خلقوا السماوات والأرض بل لا يوقنون»: أم خلقوا السماواتِ والأرض؟ لم يخلقوها، بل هم لا يوقنون؛ ففي هذا حجّةٌ على أنّ الخالقَ هو الله وحده؛ فأيقن بأنّ خالقَ السماواتِ والأرضِ هو الله، فوحّده وحده، فمن لم يخلق شيئًا لا يستحقّ العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ خالقِ السماواتِ والأرض، والإيقانُ بذلك."},"action":{"text":"تأمّل حجّةَ التوحيد: أم خلق هؤلاء المشركون السماواتِ والأرض؟ لم يخلقوها قطعًا، ولا يدّعون ذلك؛ فتعيّن أنّ خالقهما هو الله وحده؛ بل هم لا يوقنون، فلو أيقنوا لعبدوا الخالقَ وحده «أم خلقوا السماوات والأرض بل لا يوقنون»؛ ففي هذا حجّةٌ قاطعةٌ على أنّ خالقَ السماواتِ والأرضِ هو الله وحده، وأنّ سببَ شركهم عدمُ اليقين؛ فلمّا لم يخلقوا السماواتِ والأرض، تعيّن أنّ الخالقَ هو الله المستحقُّ للعبادة؛ فاعلم أنت أنّ خالقَ السماواتِ والأرضِ هو الله وحده؛ ولئن سألتهم من خلق السماواتِ والأرضَ ليقولنّ الله؛ فوحّد الله الخالقَ في العبادةِ كما تفرّد بالخلق؛ فمن كان خالقًا للسماواتِ والأرضِ فهو المستحقُّ للعبادةِ وحده؛ فمن لم يخلق شيئًا من الأصنامِ والأندادِ لا يستحقّ العبادة؛ أفمن يخلق كمن لا يخلق؛ فمن أيقن بأنّ الله خالقُ كلِّ شيءٍ وحّده وعبده؛ فاجعل توحيدَ خالقِ السماواتِ والأرضِ والإيقانَ به دأبك."}},{"n":37,"reflection":{"text":"«أم عندهم خزائن ربك أم هم المصيطرون»: أعندهم خزائنُ رزقِ ربّك ورحمته حتى يعطوا من شاؤوا؟ أم هم المسلّطون المتحكّمون؟ ففي هذا نفيُ أن يكون لهم من الأمرِ شيء؛ فاعلم أنّ الخزائنَ والأمرَ كلَّه لله، فاطلب من الله وحده، فلا يملك أحدٌ خزائنَ الله ولا يتحكّم في أمره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الخيرِ من الله وحده، وإدراكُ أنّ الخزائنَ والأمرَ له."},"action":{"text":"تأمّل نفيَ ملكهم للأمر: أعند هؤلاء المشركين خزائنُ ربّك من الرزقِ والرحمةِ والنبوّةِ والخير، حتى يتصرّفوا فيها ويعطوا من شاؤوا ويمنعوا من شاؤوا؟ أم هم المصيطرون المسلّطون المتحكّمون في الأمورِ الغالبون عليها؟ لا شيءَ من ذلك «أم عندهم خزائن ربك أم هم المصيطرون»؛ ففي هذا نفيٌ أن يكون للمشركين من الأمرِ والخزائنِ شيء، وإثباتٌ أنّ الأمرَ كلَّه لله؛ فليس عندهم خزائنُ الله ولا هم متحكّمون؛ فاعلم أنت أنّ خزائنَ الله ورزقه ورحمته وفضله بيده وحده، والأمرُ كلُّه له؛ أهم يقسمون رحمةَ ربّك؛ قل لو أنتم تملكون خزائنَ رحمةِ ربّي إذًا لأمسكتم خشيةَ الإنفاق؛ ولله خزائنُ السماواتِ والأرض؛ فاطلب الخيرَ والرزقَ والرحمةَ من الله وحده، لا من الخلق؛ فلا يملك أحدٌ خزائنَ الله ولا يتحكّم في أمره وقدره؛ فمن طلب من الله وحده كُفِي، ومن طلب من الخلقِ خاب؛ فاجعل طلبَ الخيرِ من الله وحده دأبك."}},{"n":38,"reflection":{"text":"«أم لهم سلم يستمعون فيه فليأت مستمعهم بسلطان مبين»: أم لهم مِرقاةٌ يصعدون بها إلى السماءِ فيستمعون الغيبَ والوحي؟ فليأتِ مستمعهم بحجّةٍ واضحةٍ على دعواهم؛ ففي هذا تعجيزهم وإبطالُ دعواهم؛ فاعلم أنّ الغيبَ لله وحده، فلا تدّعِ علمًا بلا دليل، فالعلمُ بالغيبِ لا يكون إلا بوحيٍ من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ العلمِ بالغيبِ لله، وطلبُ الدليلِ على كلِّ دعوى."},"action":{"text":"تأمّل تعجيزهم: أم لهؤلاء المشركين سلّمٌ ومرقاةٌ يصعدون بها إلى السماء، فيستمعون عليها إلى الملأِ الأعلى والوحيِ والغيب، حتى يعلموا أنهم على حق؟ فليأتِ مستمعهم الذي زعم أنه استمع بسلطانٍ مبينٍ وحجّةٍ واضحةٍ على دعواه «أم لهم سلم يستمعون فيه فليأت مستمعهم بسلطان مبين»؛ ففي هذا تعجيزٌ للمشركين وإبطالٌ لدعواهم أنهم على علمٍ أو حق؛ فليس لهم سلّمٌ يستمعون به الغيب، ولا حجّةَ لهم؛ فاعلم أنت أنّ الغيبَ لله وحده، لا يعلمه إلا من أطلعه الله عليه من رسله؛ قل لا يعلم من في السماواتِ والأرضِ الغيبَ إلا الله؛ عالمُ الغيبِ فلا يُظهِر على غيبه أحدًا إلا من ارتضى من رسول؛ فلا تدّعِ أنت علمًا بلا دليل، ولا تقل ما ليس لك به علم؛ واطلب الدليلَ على كلِّ دعوى؛ قل هاتوا برهانكم إن كنتم صادقين؛ فالعلمُ بالغيبِ لا يكون إلا بوحيٍ من الله؛ فمن ردَّ الغيبَ لله وطلب الدليلَ سلم، ومن ادّعى بلا دليلٍ ضلّ؛ فاجعل ردَّ العلمِ بالغيبِ لله وطلبَ الدليلِ دأبك."}},{"n":39,"reflection":{"text":"«أم له البنات ولكم البنون»: ألله البناتُ (كما تزعمون) ولكم البنون؟ ففي هذا إبطالُ نسبتهم البناتِ لله؛ فاحذر نسبةَ النقصِ إلى الله، ونزّهه عن كلِّ ما لا يليق به، فنسبةُ الولدِ والبناتِ إلى الله باطلٌ وظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن كلِّ نقص، والحذرُ من نسبةِ الباطلِ إليه."},"action":{"text":"تأمّل إبطالَ نسبتهم البنات: ألله البناتُ التي تكرهونها لأنفسكم وتنسبونها إليه (بزعمهم أنّ الملائكةَ بناتُ الله)، ولكم البنون الذين تحبّونهم وتؤثرونهم؟ فكيف تنسبون إليه ما تكرهون لأنفسكم؟ «أم له البنات ولكم البنون»؛ ففي هذا إبطالٌ لنسبةِ المشركين البناتِ إلى الله، وبيانُ تناقضهم وظلمهم في القسمة؛ فنسبوا إليه ما يكرهون؛ فاحذر أنت نسبةَ النقصِ والولدِ والصاحبةِ إلى الله؛ ونزّهه عن كلِّ ما لا يليق بجلاله؛ ويجعلون لله البناتِ سبحانه ولهم ما يشتهون؛ وجعلوا له من عباده جزءًا؛ ما اتّخذ الله من ولدٍ وما كان معه من إله؛ لم يلد ولم يولد؛ فنسبةُ الولدِ والبناتِ إلى الله باطلٌ وظلمٌ عظيم؛ تكاد السماواتُ يتفطّرن منه؛ فمن نزّه الله عن النقصِ عظّمه، ومن نسب إليه الباطلَ ظلم؛ فاجعل تنزيهَ الله عن كلِّ نقصٍ والحذرَ من نسبةِ الباطلِ إليه دأبك."}},{"n":40,"reflection":{"text":"«أم تسألهم أجرا فهم من مغرم مثقلون»: أم تسألهم، يا محمدُ، على تبليغِ الرسالةِ أجرًا فهم مثقَلون بالغرامةِ فأعرضوا؟ ففي هذا نفيُ أن يكون للإعراضِ سببٌ من جهةِ النبيّ؛ فاعلم أنّ الدعاةَ إلى الله لا يسألون أجرًا، فادعُ إلى الله محتسبًا لا طامعًا، فالإخلاصُ في الدعوةِ من صفاتِ الرسل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في الدعوةِ دون طلبِ أجر، اقتداءً بالرسل."},"action":{"text":"تأمّل نفيَ سؤالِ الأجر: أم تسألهم، يا محمدُ، على تبليغِ الرسالةِ والدعوةِ أجرًا وجُعلًا، فهم من غرامةٍ ومغرمٍ يُثقِلهم ويُرهِقهم فأعرضوا عنك؟ لا، فأنت لا تسألهم أجرًا، بل تدعوهم مجّانًا محتسبًا «أم تسألهم أجرا فهم من مغرم مثقلون»؛ ففي هذا نفيٌ أن يكون إعراضُ المشركين بسببِ طلبِ النبيِّ أجرًا منهم؛ فهو لا يسألهم أجرًا، فلا عذرَ لهم في الإعراض؛ فاعلم أنت أنّ الرسلَ والدعاةَ إلى الله لا يسألون الناسَ أجرًا على الدعوة؛ وما أسألكم عليه من أجرٍ إن أجري إلا على ربِّ العالمين؛ قل ما أسألكم عليه من أجرٍ وما أنا من المتكلّفين؛ اتّبعوا من لا يسألكم أجرًا وهم مهتدون؛ فادعُ أنت إلى الله محتسبًا مخلصًا لا طامعًا في أجرٍ من الناس؛ فالإخلاصُ في الدعوةِ وعدمُ طلبِ الأجرِ من صفاتِ الرسلِ وأتباعهم؛ فمن دعا إلى الله محتسبًا نال أجره من الله، ومن طلب أجرًا من الناسِ نقص إخلاصه؛ فاجعل الإخلاصَ في الدعوةِ دون طلبِ أجرٍ دأبك."}},{"n":41,"reflection":{"text":"«أم عندهم الغيب فهم يكتبون»: أعندهم علمُ الغيبِ فهم يكتبونه ويحكمون به؟ ففي هذا نفيُ علمهم بالغيب؛ فاعلم أنّ الغيبَ لله وحده، فلا تحكم في أمرِ الدينِ بالظنِّ والتخمين، بل بالعلمِ والوحي، فالغيبُ لا يعلمه إلا الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ الغيبِ لله، والحكمُ في الدينِ بالعلمِ لا بالظن."},"action":{"text":"تأمّل نفيَ علمهم بالغيب: أعند هؤلاء المشركين علمُ الغيبِ المكنون، فهم يكتبونه ويطّلعون عليه ويحكمون به على أنّ ما هم عليه حق، وأنه لا بعثَ ولا حساب؟ لا، فليس عندهم علمُ الغيب «أم عندهم الغيب فهم يكتبون»؛ ففي هذا نفيٌ أن يكون عند المشركين علمُ الغيب؛ فلا يعلمون الغيبَ ولا يكتبونه؛ فكيف يحكمون بما لا علمَ لهم به؟ فاعلم أنت أنّ الغيبَ لله وحده، لا يعلمه سواه؛ وعنده مفاتحُ الغيبِ لا يعلمها إلا هو؛ قل لا يعلم من في السماواتِ والأرضِ الغيبَ إلا الله؛ فلا تحكم أنت في أمرِ الدينِ والغيبِ بالظنِّ والتخمينِ والحدس؛ بل احكم بالعلمِ والوحيِ والدليل؛ ولا تقف ما ليس لك به علم؛ إن يتّبعون إلا الظنّ؛ فالغيبُ لا يعلمه إلا الله، فمن ادّعى علمه كذب؛ فمن ردَّ الغيبَ لله وحكم بالعلمِ سلم، ومن حكم بالظنِّ ضلّ؛ فاجعل ردَّ الغيبِ لله والحكمَ في الدينِ بالعلمِ دأبك."}},{"n":42,"reflection":{"text":"«أم يريدون كيدا فالذين كفروا هم المكيدون»: أم يريدون كيدًا بك وبدينك؟ فالذين كفروا هم المكيدون الذين يعود كيدهم عليهم؛ ففي هذا بيانُ أنّ كيدَ الكافرين يرتدّ عليهم؛ فلا تخف كيدَ أهلِ الباطل، فكيدهم يعود عليهم، فتوكّل على الله فهو كافيك كيدهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ على الله، وعدمُ الخوفِ من كيدِ الكافرين."},"action":{"text":"تأمّل أنّ كيدَ الكافرين يرتدّ عليهم: أم يريد هؤلاء الكافرون كيدًا ومكرًا بك، يا محمدُ، وبدينك، ليبطلوا الحقَّ ويطفئوا النور؟ فالذين كفروا هم المكيدون المغلوبون الذين يعود كيدهم ومكرهم عليهم، فيُهلَكون به «أم يريدون كيدا فالذين كفروا هم المكيدون»؛ ففي هذا بيانُ أنّ كيدَ الكافرين بالحقِّ وأهله يرتدّ عليهم ويعود عليهم بالخسران؛ فمكرهم يحيق بهم؛ فلا تخف أنت كيدَ أهلِ الباطلِ ومكرهم بالحقِّ وأهله؛ فكيدهم يعود عليهم؛ ولا يحيق المكرُ السيّئ إلا بأهله؛ وقد مكروا مكرهم وعند الله مكرهم؛ ومكروا ومكر الله والله خيرُ الماكرين؛ إنّ كيدَ الشيطانِ كان ضعيفًا؛ فتوكّل على الله فهو كافيك كيدهم؛ ومن يتوكّل على الله فهو حسبه؛ فمن توكّل على الله ولم يخف كيدَ الكافرين كفاه الله، ومن خاف كيدهم واعتمد على نفسه خُذِل؛ فاجعل التوكّلَ على الله وعدمَ الخوفِ من كيدِ الكافرين دأبك."}},{"n":43,"reflection":{"text":"«أم لهم إله غير الله سبحان الله عما يشركون»: أم لهم معبودٌ غيرُ الله يستحقّ العبادة؟ تنزّه الله عمّا يشركون؛ ففي هذا نفيُ استحقاقِ غيرِ الله للعبادة، وتنزيهُه عن الشرك؛ فوحّد الله ونزّهه عن الشرك، فلا معبودَ بحقٍّ سواه، فأخلص عبادتك له وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله وتنزيهُه عن الشرك، وإخلاصُ العبادةِ له."},"action":{"text":"تأمّل نفيَ الشريك: أم لهؤلاء المشركين إلهٌ غيرُ الله يستحقّ العبادةَ ويقدر على نفعهم وضرّهم؟ لا؛ تنزّه الله وتقدّس عمّا يشركون به من الأندادِ والأصنام «أم لهم إله غير الله سبحان الله عما يشركون»؛ ففي هذا نفيٌ أن يكون لهم إلهٌ غيرُ الله يستحقّ العبادة، وتنزيهٌ لله عن الشرك؛ فلا معبودَ بحقٍّ إلا الله؛ فاختُتِمت الأسئلةُ التعجيزيةُ بإثباتِ التوحيدِ وتنزيهِ الله؛ فوحّد أنت الله ونزّهه عن الشركِ وعن كلِّ ما لا يليق به؛ فلا معبودَ بحقٍّ سواه؛ لو كان فيهما آلهةٌ إلا الله لفسدتا؛ وما من إلهٍ إلا الله؛ سبحان الله عمّا يصفون؛ فأخلص عبادتك ودعاءك وخوفك ورجاءك لله وحده؛ واعبدوا الله ولا تشركوا به شيئًا؛ فمن وحّد الله ونزّهه عن الشركِ نجا، ومن أشرك هلك؛ فاجعل توحيدَ الله وتنزيهَه وإخلاصَ العبادةِ له دأبك."}}]},{"title":"عنادُ المشركين، والأمرُ بالصبرِ والتسبيح","range":[44,49],"theme":"شدّةُ عنادهم حتى لو رأوا كسفًا من السماءِ ساقطًا قالوا سحابٌ مركوم، والأمرُ بتركهم حتى يلاقوا يومهم الذي فيه يُصعَقون فلا يُغني كيدهم، وأنّ للظالمين عذابًا دون ذلك، وأمرُ النبيِّ بالصبرِ لحكمِ ربّه فإنه بأعينِ الله وبالتسبيحِ حين يقوم ومن الليلِ وإدبارِ النجوم","verses":[{"n":44,"reflection":{"text":"«وإن يروا كسفا من السماء ساقطا يقولوا سحاب مركوم»، وإن يروا قطعةً من السماءِ ساقطةً عليهم عذابًا يقولوا: هذا سحابٌ متراكم؛ ففي هذا بيانُ شدّةِ عنادهم؛ فاحذر العنادَ الذي يردّ الآياتِ ولو رآها عيانًا، فاقبل الحقَّ ولا تعاند، فالعنادُ يعمي عن أوضحِ الآيات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ وتركُ العناد، وإدراكُ أنّ العنادَ يعمي عن الآيات."},"action":{"text":"تأمّل شدّةَ عنادهم: وإن يرَ هؤلاء المعاندون قطعةً وكسفًا من السماءِ ساقطًا عليهم عذابًا وعقوبة، لا يؤمنون، بل يقولون معاندين: هذا سحابٌ مركومٌ متراكمٌ بعضه فوق بعض، يُمطِرنا؛ فلا يعتبرون ولا يؤمنون «وإن يروا كسفا من السماء ساقطا يقولوا سحاب مركوم»؛ ففي هذا بيانُ شدّةِ عنادِ المشركين، حتى لو رأوا العذابَ عيانًا نازلًا لتأوّلوه ولم يؤمنوا؛ فعنادهم يمنعهم من قبولِ أوضحِ الآيات؛ فاحذر أنت العنادَ الذي يردّ الحقَّ والآياتِ ولو رآها عيانًا؛ ولو فتحنا عليهم بابًا من السماءِ فظلّوا فيه يعرجون، لقالوا إنما سُكِّرت أبصارنا بل نحن قومٌ مسحورون؛ ولو أنزلنا عليك كتابًا في قرطاسٍ فلمسوه بأيديهم لقال الذين كفروا إن هذا إلا سحرٌ مبين؛ فالعنادُ يعمي عن أوضحِ الآياتِ والبراهين؛ فاقبل أنت الحقَّ عند وضوحه ولا تعاند؛ فمن قبل الحقَّ اهتدى، ومن عاند ضلّ ولو رأى الآيات؛ فاجعل قبولَ الحقِّ وتركَ العنادِ دأبك."}},{"n":45,"reflection":{"text":"«فذرهم حتى يلاقوا يومهم الذي فيه يصعقون»: فاتركهم، يا محمدُ، حتى يلاقوا يومهم الذي يُصعَقون فيه (يومَ القيامةِ أو بدر)؛ ففي هذا الأمرُ بالإعراضِ عن المعاندين وتفويضِ أمرهم لله؛ فأعرض عن المعاندين بعد البلاغ، وفوّض أمرهم إلى الله، فالله كافيك أمرهم، فلا تحمل همّهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإعراضُ عن المعاندين وتفويضُ أمرهم لله بعد البلاغ."},"action":{"text":"تأمّل الأمرَ بالإعراض: فذرهم، يا محمدُ، واتركهم في عنادهم وتكذيبهم، ولا تحمل همّهم؛ حتى يلاقوا يومهم الذي فيه يُصعَقون، أي يُهلَكون ويموتون، أو يومَ القيامةِ الذي فيه هلاكهم، أو يومَ بدرٍ الذي صُعِقوا فيه بالقتل «فذرهم حتى يلاقوا يومهم الذي فيه يصعقون»؛ ففي هذا الأمرُ للنبيِّ بالإعراضِ عن المعاندين بعد البلاغ، وتفويضِ أمرهم إلى الله حتى يأتيهم عذابه؛ فأمره بتركهم لعلمه بعنادهم؛ فأعرض أنت عن المعاندين المصرّين بعد أن بلّغتهم الحقّ؛ وفوّض أمرهم إلى الله، فهو كافيك إياهم؛ فتولَّ عنهم فما أنت بملوم؛ فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم؛ فاصفح الصفحَ الجميل؛ فالله كافيك أمرَ المعاندين؛ فلا تحمل همّهم ولا تشغل قلبك بهم؛ فمن أعرض عن المعاندِ وفوّض أمره لله أراح نفسه، ومن حمل همّهم أتعبها؛ فاجعل الإعراضَ عن المعاندين وتفويضَ أمرهم لله بعد البلاغ دأبك."}},{"n":46,"reflection":{"text":"«يوم لا يغني عنهم كيدهم شيئا ولا هم ينصرون»: يومَ لا ينفعهم كيدهم ومكرهم شيئًا، ولا يجدون ناصرًا ينصرهم؛ ففي هذا بيانُ عجزِ الكافرين يومَ القيامة؛ فاعلم أنّ كيدَ الكافرين ونصرَهم لأنفسهم لا ينفعهم يومَ القيامة، فاعتمد على الله لا على كيدك، فالنجاةُ في الإيمانِ لا في الكيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتمادُ على الله لا على الكيد، وإدراكُ عجزِ الكافرين يومئذ."},"action":{"text":"تأمّل عجزَ الكافرين: ذلك اليومُ الذي يُصعَقون فيه، هو يومَ لا يُغني عنهم كيدهم ومكرهم الذي كادوه في الدنيا شيئًا، ولا يدفع عنهم العذاب؛ ولا هم يُنصَرون، فلا يجدون ناصرًا ينصرهم من عذابِ الله «يوم لا يغني عنهم كيدهم شيئا ولا هم ينصرون»؛ ففي هذا بيانُ عجزِ الكافرين يومَ القيامة، فلا كيدهم ينفعهم ولا ناصرَ لهم؛ فيبطل كيدهم ويُخذَلون؛ فاعلم أنت أنّ كيدَ الكافرين ومكرهم ونصرَ بعضهم بعضًا لا ينفعهم يومَ القيامة؛ فما لهم من قوّةٍ ولا ناصر؛ يومَ لا تملك نفسٌ لنفسٍ شيئًا والأمرُ يومئذٍ لله؛ فما له من قوّةٍ ولا ناصر؛ فاعتمد أنت على الله وحده لا على كيدك ولا حيلتك؛ فالنجاةُ يومَ القيامةِ في الإيمانِ والعملِ الصالح، لا في الكيدِ والحيلة؛ فمن اعتمد على الله نجا، ومن اعتمد على كيده خُذِل؛ فاجعل الاعتمادَ على الله لا على الكيدِ دأبك."}},{"n":47,"reflection":{"text":"«وإن للذين ظلموا عذابا دون ذلك ولكن أكثرهم لا يعلمون»، وإنّ للذين ظلموا (كفروا) عذابًا في الدنيا دون عذابِ الآخرة، ولكنّ أكثرهم لا يعلمون؛ ففي هذا بيانُ أنّ للظالمين عذابًا معجّلًا في الدنيا؛ فاحذر الظلمَ والكفرَ فإنّ لهما عذابًا في الدنيا قبل الآخرة، فبادر بالتوبةِ قبل نزولِ العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ الموجبِ لعذابِ الدنيا، والمبادرةُ بالتوبة."},"action":{"text":"تأمّل عذابَ الدنيا للظالمين: وإنّ للذين ظلموا أنفسهم بالكفرِ والتكذيبِ عذابًا في الدنيا دون عذابِ الآخرةِ الأكبر: كالقتلِ والأسرِ والقحطِ والمصائبِ وعذابِ القبر؛ ولكنّ أكثرهم لا يعلمون ذلك، فلا يعتبرون «وإن للذين ظلموا عذابا دون ذلك ولكن أكثرهم لا يعلمون»؛ ففي هذا بيانُ أنّ للظالمين عذابًا معجّلًا في الدنيا قبل عذابِ الآخرة، وأنّ أكثرهم غافلون عنه؛ فيُعذّبون في الدنيا بأنواعِ العقوبات؛ فاحذر أنت الظلمَ والكفرَ والمعاصيَ فإنّ لها عذابًا في الدنيا قبل الآخرة؛ ولنذيقنّهم من العذابِ الأدنى دون العذابِ الأكبر لعلّهم يرجعون؛ ظهر الفسادُ في البرِّ والبحرِ بما كسبت أيدي الناس؛ فبادر بالتوبةِ والإيمانِ والعملِ الصالحِ قبل نزولِ العذاب؛ فمن تاب وأناب نجا من عذابِ الدنيا والآخرة، ومن ظلم وأصرّ ناله العذابُ في الدارين؛ فاجعل الحذرَ من الظلمِ والمبادرةَ بالتوبةِ دأبك."}},{"n":48,"reflection":{"text":"«واصبر لحكم ربك فإنك بأعيننا وسبح بحمد ربك حين تقوم»، واصبر، يا محمدُ، لحكمِ ربّك وقضائه، فإنك بأعيننا وحفظنا ورعايتنا، وسبّح بحمدِ ربّك حين تقوم؛ ففي هذا الأمرُ بالصبرِ والتسبيح مع البشارةِ بالحفظِ الإلهي؛ فاصبر لقضاءِ الله واستعن بالتسبيح، واعلم أنك في حفظِ الله ورعايته، فالصبرُ مع معيّةِ الله سبيلُ الطمأنينة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ لحكمِ الله والاستعانةُ بالتسبيح، والطمأنينةُ لحفظه."},"action":{"text":"تأمّل الأمرَ بالصبرِ مع الحفظ: واصبر، يا محمدُ، لحكمِ ربّك وقضائه القدريِّ والشرعيّ، على أذى المكذّبين وتأخيرِ النصر؛ فإنك بأعيننا، أي في حفظنا ورعايتنا وكلاءتنا وحمايتنا، نراك ونحوطك؛ وسبّح بحمدِ ربّك ونزّهه حامدًا حين تقوم من نومك أو من مجلسك أو إلى الصلاة «واصبر لحكم ربك فإنك بأعيننا وسبح بحمد ربك حين تقوم»؛ ففي هذا الأمرُ بالصبرِ لحكمِ الله والاستعانةِ بالتسبيح، مع البشارةِ العظيمةِ بأنّ النبيَّ في حفظِ الله ورعايته؛ فطمأنه بالمعيّةِ والحفظِ ليصبر؛ فاصبر أنت لحكمِ ربّك القدريِّ والشرعيّ، على المصائبِ والتكاليفِ وأذى الناس؛ واستعن على الصبرِ بالتسبيحِ والحمدِ والذكر؛ واعلم أنك في حفظِ الله ورعايته إن اتّقيته؛ إنّ الله مع الذين اتّقوا؛ ولتُصنَع على عيني؛ واصنعِ الفلكَ بأعيننا؛ فالصبرُ لحكمِ الله مع استحضارِ معيّته وحفظه سبيلُ الطمأنينةِ والثبات؛ فمن صبر لحكمِ الله وأيقن بحفظه اطمأنّ، ومن جزع تعب؛ فاجعل الصبرَ لحكمِ الله والاستعانةَ بالتسبيحِ والطمأنينةَ لحفظه دأبك."}},{"n":49,"reflection":{"text":"«ومن الليل فسبحه وإدبار النجوم»، ومن الليلِ فسبّح ربّك (بصلاةِ الليل)، وسبّحه إدبارَ النجوم (عند إدبارِ الليلِ وطلوعِ الفجر)؛ ففي هذا الأمرُ بتسبيحِ الليلِ وآخره؛ فأكثر من ذكرِ الله وتسبيحه في الليلِ وعند السحر، فالتسبيحُ في هذه الأوقاتِ من أفضلِ العبادات، فداوم عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من تسبيحِ الله في الليلِ وعند السحر."},"action":{"text":"تأمّل الأمرَ بتسبيحِ الليل: ومن الليلِ فسبّح ربّك ونزّهه بصلاةِ الليلِ والتهجّدِ والذكر؛ وسبّحه إدبارَ النجوم، أي عند إدبارِ الليلِ واختفاءِ النجومِ بطلوعِ الفجر، وهي صلاةُ الفجرِ أو ركعتاه «ومن الليل فسبحه وإدبار النجوم»؛ ففي هذا الأمرُ بتسبيحِ الله وذكره في الليل (بالتهجّد)، وعند إدبارِ النجومِ وطلوعِ الفجر؛ فهذه أوقاتُ فضلٍ للعبادة؛ فأكثر أنت من ذكرِ الله وتسبيحه وصلاته في الليلِ وعند السحرِ والفجر؛ ومن الليلِ فتهجّد به نافلةً لك؛ وسبّح بحمدِ ربّك قبل طلوعِ الشمسِ وقبل غروبها، ومن آناءِ الليلِ فسبّح وأطرافَ النهار؛ كانوا قليلًا من الليلِ ما يهجعون؛ فالتسبيحُ والعبادةُ في الليلِ وعند السحرِ والفجرِ من أفضلِ العباداتِ وأزكاها؛ فمن داوم عليها نال الفضلَ والقربَ من الله، ومن غفل عنها حُرِم؛ فاجعل الإكثارَ من تسبيحِ الله في الليلِ وعند السحرِ والفجرِ دأبك."}}]}],"coverage":{"covered":49,"total":49}};
